// Character sheet markup (templates/ttrpg/character_sheet.html) rendered from
// GET /api/v1/characters/:id/page. onclick handlers call the verbatim-ported
// sheet.js functions exposed on window for the life of the view.
import { html, raw } from '../../../lib/dom.js';

const sgn = n => (n >= 0 ? '+' : '') + n;
const J = v => JSON.stringify(v);
const ordLvl = l => l === 0 ? 'Cantrip' : l + (l === 1 ? 'st' : l === 2 ? 'nd' : l === 3 ? 'rd' : 'th') + ' lvl';
const levelHead = l => l === 0 ? 'Cantrips' : l === 1 ? '1st Level' : l === 2 ? '2nd Level' : l === 3 ? '3rd Level' : l + 'th Level';
const pill = n => n ? html` <span class="badge rounded-pill" style="background:var(--ttrpg-accent);color:var(--sp-on-accent);font-size:.65rem;">${n}</span>` : '';
const editBox = (type, id, inner) => html`<div id="${type}-edit-${id}" class="mb-2 p-2" style="display:none;background:var(--sp-bg);border:1px solid var(--sp-border);border-radius:6px;"><div class="d-flex gap-2 flex-wrap align-items-center">${inner}
  <button class="btn btn-ttrpg btn-sm" onclick="${({ res: 'saveResource', skill: 'saveSkill', item: 'saveItem' })[type]}(${id})">Save</button>
  <button type="button" class="btn btn-outline-secondary btn-sm" onclick="editToggle('${type}', ${id})">Cancel</button></div></div>`;
const suggest = (id, extra = '') => html`<div id="${id}" style="display:none;position:absolute;top:100%;left:0;right:0;z-index:200;${raw(extra)}background:var(--sp-surface);border:1px solid var(--sp-border);border-radius:0 0 6px 6px;max-height:220px;overflow-y:auto;"></div>`;
const dccArmorLabel = a => (a.notes || 'DR').split(' — ')[0];

export const STYLE = `
  .attr-box{background:color-mix(in srgb,var(--sp-accent) 12%,transparent);border:1px solid var(--ttrpg-accent);border-radius:6px;text-align:center;padding:6px 4px;flex:1 1 56px;min-width:56px;}
  .attr-box .score{font-size:1.3rem;font-weight:bold;color:var(--ttrpg-accent);line-height:1.15;} .attr-box .mod{font-size:.72rem;color:var(--sp-muted);}
  .attr-box .label{font-size:.6rem;text-transform:uppercase;letter-spacing:.05em;color:var(--sp-muted);}
  .editable{cursor:pointer;border-bottom:1px dashed var(--ttrpg-accent);} .editable:hover{background:color-mix(in srgb,var(--sp-accent) 10%,transparent);border-radius:3px;}
  .attr-step{display:flex;align-items:center;justify-content:center;gap:3px;} .attr-step .score,.attr-step .mod{min-width:24px;}
  .attr-stepbtn{width:18px;height:18px;padding:0;line-height:1;font-size:.85rem;flex-shrink:0;color:var(--sp-muted);background:transparent;border:1px solid var(--sp-border);border-radius:3px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;}
  .attr-stepbtn:hover{border-color:var(--ttrpg-accent);color:var(--ttrpg-accent);}
  .hp-bar-wrap{height:16px;background:var(--sp-border);border-radius:4px;overflow:hidden;} .hp-bar-fill{height:100%;transition:width .4s,background .4s;border-radius:4px;}
  #sheetTabs.nav-tabs{flex-wrap:nowrap;overflow-x:auto;gap:0;border-bottom:1px solid var(--sp-border);scrollbar-width:none;} #sheetTabs.nav-tabs::-webkit-scrollbar{display:none;}
  #sheetTabs .nav-item{flex-shrink:0;margin-bottom:0;}
  #sheetTabs .nav-link{border:none!important;border-bottom:2px solid transparent!important;border-radius:0!important;background:transparent!important;color:var(--sp-muted)!important;font-size:.78rem;font-weight:600;padding:9px 13px;margin-bottom:-1px;white-space:nowrap;transition:color .15s,border-color .15s;}
  #sheetTabs .nav-link:hover{color:var(--ttrpg-text)!important;} #sheetTabs .nav-link.active{color:var(--ttrpg-accent)!important;border-bottom-color:var(--ttrpg-accent)!important;background:transparent!important;}
  .feat-chip{display:inline-block;font-size:.75rem;padding:2px 8px;border-radius:12px;border:1px solid var(--sp-border);color:var(--ttrpg-accent);background:color-mix(in srgb,var(--sp-accent) 10%,transparent);cursor:default;white-space:nowrap;}
  .feat-chip:hover{background:color-mix(in srgb,var(--sp-accent) 22%,transparent);}
  .feat-tooltip .tooltip-inner{max-width:300px;text-align:left;white-space:pre-wrap;font-size:.8rem;background:var(--sp-surface);border:1px solid var(--ttrpg-accent);color:var(--ttrpg-text);} .feat-tooltip .tooltip-arrow::before{border-bottom-color:var(--ttrpg-accent);}
  .dice-btn{min-width:38px;transition:background .15s;} .dice-btn.active{background:var(--ttrpg-accent)!important;color:var(--sp-on-accent)!important;border-color:var(--ttrpg-accent)!important;}
  .stat-mod-btn{min-width:44px;line-height:1.1;padding:2px 4px;}
  .die-val{display:inline-block;padding:1px 6px;border-radius:4px;background:color-mix(in srgb,var(--sp-accent) 18%,transparent);border:1px solid var(--sp-border);margin:1px;font-weight:600;}
  .die-val.nat20{background:#856404;border-color:#ffc107;color:#fff200;} .die-val.nat1{background:#6b1a1a;border-color:#dc3545;color:#ffaaaa;} .die-val.kept{outline:2px solid var(--ttrpg-accent);} .die-val.dropped{opacity:.4;text-decoration:line-through;}
  .feed-entry{font-size:.78rem;padding:5px 0;border-bottom:1px solid var(--sp-border);} .feed-entry .expr{color:var(--sp-muted);} .feed-entry .tot{color:var(--ttrpg-accent);font-weight:bold;font-size:.95rem;}
  .spell-popover .popover{max-width:300px;} .spell-popover .popover-header{background:var(--ttrpg-primary);color:var(--ttrpg-accent);font-size:.8rem;font-weight:bold;border-bottom-color:var(--ttrpg-accent);}
  .spell-popover .popover-body{background:var(--ttrpg-surface);color:var(--ttrpg-text);font-size:.78rem;white-space:normal;line-height:1.4;}
  .dice-quickref{border-top:1px solid var(--sp-border);padding-top:8px;margin-top:10px;}
  .qref-title{font-size:.7rem;text-transform:uppercase;letter-spacing:.06em;color:var(--sp-muted);font-weight:600;margin-bottom:6px;} .qref-hint{text-transform:none;letter-spacing:0;font-weight:400;font-size:.68rem;}
  .qref-row{display:flex;gap:6px;align-items:flex-start;margin-bottom:5px;} .qref-label{flex-shrink:0;width:56px;font-size:.62rem;text-transform:uppercase;color:var(--sp-muted);padding-top:3px;letter-spacing:.04em;}
  .qref-chips{display:flex;flex-wrap:wrap;gap:4px;flex:1;min-width:0;}
  .qref-chip{display:inline-flex;align-items:center;gap:3px;font-size:.72rem;padding:2px 7px;border-radius:10px;border:1px solid var(--sp-border);color:var(--ttrpg-text);background:var(--ttrpg-surface);white-space:nowrap;}
  .qref-sub{color:var(--sp-muted);font-size:.66rem;} .qref-click{cursor:pointer;} .qref-click:hover{border-color:var(--ttrpg-accent);color:var(--ttrpg-accent);} .qref-click:hover .qref-sub{color:var(--ttrpg-accent);}
  :where(.ttrpg-card) *{color:var(--ttrpg-text)!important;} .ttrpg-card .btn-ttrpg{color:var(--sp-on-accent)!important;} .ttrpg-card .badge{color:var(--sp-on-accent)!important;}
  .ttrpg-card .die-val.nat20{color:#fff200!important;} .ttrpg-card .die-val.nat1{color:#ffaaaa!important;}
`;

export function render(d) {
  const c = d.char, dcc = d.dcc, IS_DCC = c.is_dcc, can = d.can_edit, isDm = d.is_dm;
  const keys = c.stat_keys;
  const races = d.races_lib, classes = d.classes_lib;
  const raceInfo = c.race ? races[c.race.toLowerCase()] : null;
  const eqW = c.weapons.filter(w => w.equipped === 1), eqA = c.armor.filter(a => a.equipped === 1);
  const prepared = c.spells.filter(s => s.prepared === 1).slice().sort((a, b) => a.spell_level - b.spell_level);
  const hot = IS_DCC ? c.inventory.filter(i => i.hotlist === 1) : [];
  const notes = c.notes.slice().sort((a, b) => (a.created_at < b.created_at ? 1 : a.created_at > b.created_at ? -1 : 0));
  const pb = Math.floor((c.level - 1) / 4) + 2;
  const modRows = keys.map(k => [k.toUpperCase(), c.stat_mods[k]]); if (!IS_DCC) modRows.push(['PROF', pb]);
  const condList = IS_DCC ? d.dcc_debuffs : d.conditions;
  const myRace = raceInfo, myClass = c.char_class ? classes[c.char_class.toLowerCase()] : null;
  const cli = d.class_level_info, feats = d.class_features;
  const raceTraits = myRace && myRace.traits_text ? myRace.traits_text.split('\n').map(t => t.trim()).filter(Boolean) : [];
  const classSubs = myClass && myClass.subclasses ? myClass.subclasses.split(',').map(t => t.trim()).filter(Boolean) : [];
  const armorTitle = a => `${a.armor_category}${a.dex_bonus ? ' + DEX' + (a.max_dex_bonus !== null ? ` (max ${a.max_dex_bonus})` : '') : ''}${a.str_minimum ? ` • STR ${a.str_minimum} req` : ''}${a.stealth_disadvantage ? ' • Stealth disadv.' : ''}${a.notes ? ' • ' + a.notes : ''}`;

  return html`<style>${raw(STYLE)}</style>
<div class="row g-3">
  <div class="col-12"><div class="ttrpg-card p-3 d-flex gap-3 align-items-start flex-wrap">
    <div>
      <div id="portrait-wrap">${c.portrait_url ? html`<img id="portrait-img" src="${c.portrait_url}" style="width:90px;height:90px;object-fit:cover;border-radius:8px;border:2px solid var(--ttrpg-accent);" alt="">`
        : html`<div id="portrait-img" style="width:90px;height:90px;border-radius:8px;border:2px solid var(--ttrpg-accent);background:var(--ttrpg-primary);display:flex;align-items:center;justify-content:center;font-size:2.5rem;color:var(--ttrpg-accent);">&#9876;</div>`}</div>
      <button class="btn btn-sm btn-outline-secondary w-100 mt-1" style="font-size:.7rem;" onclick="openLlmPrompt()" title="Generate image prompt">&#127748; Image Prompt</button>
      ${can ? html`<button class="btn btn-sm btn-outline-secondary w-100 mt-1" style="font-size:.7rem;" id="paste-portrait-btn" onclick="activatePastePortrait()" title="Paste an image from clipboard">&#128203; Paste Portrait</button>
        <form id="portrait-form" enctype="multipart/form-data" class="mt-1"><input type="file" name="portrait" id="portraitInput" class="d-none" accept="image/*"><label for="portraitInput" class="btn btn-sm btn-outline-secondary w-100" style="font-size:.7rem;">Change</label></form>
        <button class="btn btn-sm btn-outline-secondary w-100 mt-1" style="font-size:.7rem;" id="reuse-portrait-btn" title="Reuse a picture already on this server — nothing is copied">&#128444; Reuse Picture</button>` : ''}
    </div>
    <div class="flex-grow-1">
      <div class="d-flex justify-content-between align-items-start flex-wrap gap-2">
        <div>${!isDm ? html`<a href="/ttrpg/my-character" class="small text-muted text-decoration-none d-block mb-1">&#8592; My Characters</a>` : ''}<h3 class="mb-0" style="color:var(--ttrpg-accent);">${c.name}</h3></div>
        <div class="d-flex gap-1 flex-wrap align-items-center">
          <button class="btn btn-sm btn-outline-secondary" onclick="toggleDicePanel()" title="Dice Roller"><span class="dice-ico">&#127922;</span></button>
          ${can ? html`<a href="/ttrpg/character/${c.character_id}/edit" class="btn btn-sm btn-outline-secondary">&#9998; Edit Sheet</a>` : ''}
          <div id="sfx-ctrl" style="display:inline-flex;align-items:center;gap:6px;background:var(--sp-surface-2);border:1px solid var(--sp-border);border-radius:16px;padding:2px 8px;font:600 12px system-ui,sans-serif;user-select:none;">
            <button id="sfx-toggle" type="button" title="Sound is on by default — click to mute / unmute" style="background:none;border:none;cursor:pointer;font:inherit;line-height:1;padding:0;white-space:nowrap;color:var(--sp-heading);">&#128266; Sound: ON</button>
            <input type="range" id="sfx-vol" min="0" max="100" value="80" title="SFX volume" style="width:64px;accent-color:var(--sp-accent);cursor:pointer;">
            <button id="sfx-choose" type="button" title="Choose which sound plays for each action" onclick="if(window.SFX)SFX.openChooser()" style="background:none;border:1px solid var(--sp-accent);border-radius:12px;cursor:pointer;font:inherit;line-height:1;padding:2px 8px;white-space:nowrap;color:var(--sp-heading);">&#9881; Sounds</button></div></div></div>
      <div class="text-muted small mt-1">Lv${c.level} ${c.char_class}
        ${c.race ? html`&bull; ${c.race} ${raceInfo ? html`<span data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="feat-tooltip" title="${[raceInfo.ability_bonuses, raceInfo.traits_text ? 'Traits: ' + raceInfo.traits_text.replace(/\n/g, ', ') : '', raceInfo.speed ? 'Speed: ' + raceInfo.speed : ''].filter(Boolean).join(' \n ')}" style="cursor:help;color:var(--ttrpg-accent);margin-left:3px;">&#9432;</span>` : ''}` : ''}
        ${c.background ? html`&bull; ${c.background}` : ''}
        ${d.dcc_pairing_warning ? html`<div class="small mt-1" style="color:#dc3545;font-weight:600;">&#9888; ${d.dcc_pairing_warning}</div>` : ''}
        ${IS_DCC && can && c.race && !(dcc.applied || []).includes('race:' + c.race) ? html`<button class="btn btn-sm btn-outline-secondary py-0 ms-1" style="font-size:.7rem;" onclick="applyLibrary('race')" title="Add this Race's Stat bonuses and Skill Ranks from the library">&#10010; Apply race bonuses</button>` : ''}
        ${IS_DCC && can && c.char_class && !(dcc.applied || []).includes('class:' + c.char_class) ? html`<button class="btn btn-sm btn-outline-secondary py-0 ms-1" style="font-size:.7rem;" onclick="applyLibrary('class')" title="Add this Class's Stat bonuses and Skill Ranks from the library">&#10010; Apply class bonuses</button>` : ''}</div>
      <div class="small text-muted">Player: ${c.user_display_name}${IS_DCC ? html` &bull; <span title="Game system">Dungeon Crawler Carl</span>${dcc.crawler_number ? html` &bull; Crawler #${dcc.crawler_number}` : ''}${dcc.pronouns ? html` &bull; ${dcc.pronouns}` : ''}` : ''}</div>
      ${IS_DCC ? html`<div class="mt-2" style="max-width:420px;">
        <div class="d-flex justify-content-between align-items-center small mb-1"><span>Health Bar <strong id="hp_pct_disp">${c.hp_pct}%</strong> <span class="text-muted">(<span id="hp_current_disp">${c.hp_current}</span> of ${c.hp_max} slots)</span></span><span class="text-muted" title="Each slot is worth your Con Mod. Damage below that is shrugged off.">each slot = ${c.hb_slot_value}</span></div>
        <div class="d-flex gap-1 mb-2" id="hb_slots">${Array.from({ length: c.hp_max }, (_, i) => html`<div class="hb-slot${i < c.hp_current ? ' full' : ''}" style="flex:1;height:22px;border:1px solid var(--ttrpg-accent);border-radius:4px;font-size:.68rem;display:flex;align-items:center;justify-content:center;background:${i < c.hp_current ? (i < 2 ? '#dc3545' : i < 5 ? '#ffc107' : '#28a745') : 'transparent'};color:${i < c.hp_current ? '#fff' : 'var(--sp-muted)'};" title="${(i + 1) * 10}%">${c.hb_slot_value}</div>`)}</div>
        <div id="hb_dying" class="small fw-bold" style="color:#dc3545;${c.hp_current > 0 ? 'display:none;' : ''}">&#9760; Dying — must be healed to 10% or more</div>
        ${can ? html`<div class="d-flex gap-1 align-items-center flex-wrap">
          <button class="btn btn-sm btn-outline-danger px-2" onclick="applyDccDamage()" title="Enter the damage number. DR (${c.dr_total}) is taken off first, then each full ${c.hb_slot_value} points costs one slot.">&#9660; Take damage</button>
          <input type="number" id="hp_amount" class="form-control form-control-sm text-center" value="5" min="0" style="max-width:64px;" title="Damage dealt to you"><span class="text-muted small">DR ${c.dr_total} comes off first</span>
          <button class="btn btn-sm btn-outline-success px-2 ms-2" onclick="applyHpDelta(+hbSlots())" title="Heal by slots (Heal spell = 2 slots = 20%)">&#9650; Heal</button>
          <input type="number" id="hb_heal_slots" class="form-control form-control-sm text-center" value="2" min="1" max="10" style="max-width:56px;" title="Slots to heal (1 slot = 10%)"><span class="text-muted small">slots</span></div>` : ''}</div>`
      : html`<div class="mt-2" style="max-width:340px;">
        <div class="d-flex justify-content-between align-items-center small mb-1"><span>HP <strong id="hp_current_disp">${c.hp_current}</strong> / ${c.hp_max}</span><span class="text-muted" id="hp_pct_disp">${c.hp_pct}%</span></div>
        <div class="hp-bar-wrap mb-2"><div class="hp-bar-fill" id="hp_bar" style="width:${c.hp_pct}%;background:${c.hp_color};"></div></div>
        ${can ? html`<div class="d-flex gap-1 align-items-center"><button class="btn btn-sm btn-outline-danger px-2" onclick="applyHpDelta(-hpAmount())" title="Apply damage">&#9660; Dmg</button><input type="number" id="hp_amount" class="form-control form-control-sm text-center" value="1" min="1" style="max-width:60px;"><button class="btn btn-sm btn-outline-success px-2" onclick="applyHpDelta(+hpAmount())" title="Apply healing">&#9650; Heal</button></div>` : ''}</div>`}
      ${IS_DCC ? html`<div class="d-flex gap-3 mt-2 flex-wrap small">
        <span title="Evade is a roll, not a number: d20 + 2 + Dex Mod + buffs, against the Mob's to-hit number">Evade <strong>d20 ${sgn(c.evade_bonus)}</strong></span><span title="Damage Resistance — subtracted from every hit before the Health Bar">DR <strong>${c.dr_total}</strong></span>
        <span>Move <strong>${dcc.move}</strong> / Step <strong>${dcc.step}</strong> ft</span><span>Size <strong>${dcc.size}</strong></span><span title="Starts at Cha Mod × 2">Popularity <strong>${dcc.popularity}</strong></span><span>AI Favor <strong>${dcc.ai_favor}</strong></span><span title="Max Mana = Intelligence score">Mana <strong>${c.mana_max}</strong></span>
        ${dcc.stat_points ? html`<span style="color:var(--ttrpg-accent);">&#9650; ${dcc.stat_points} Stat points to spend</span>` : ''}</div>`
      : html`<div class="d-flex gap-3 mt-2 flex-wrap small"><span>AC <strong>${c.ac}</strong></span><span>Speed <strong>${c.speed}</strong></span><span>Init <strong>${sgn(c.initiative_bonus)}</strong></span><span>Pass. Perc. <strong>${c.passive_perception}</strong></span></div>`}
      ${eqW.length || eqA.length ? html`<div class="d-flex flex-wrap gap-1 mt-2">
        ${eqW.map(w => html`<span style="font-size:.75rem;padding:2px 8px;border-radius:10px;background:color-mix(in srgb, var(--sp-accent) 10%, transparent);border:1px solid var(--sp-border);color:var(--ttrpg-accent);" title="${w.weapon_category}${w.weapon_range ? ' ' + w.weapon_range : ''}${w.properties ? ' • ' + w.properties : ''}${w.notes ? ' • ' + w.notes : ''}" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="feat-tooltip">&#9876; ${w.weapon_name}${w.damage_dice ? html` <span style="color:var(--sp-muted);font-size:.7rem;">${w.damage_dice}${w.damage_bonus ? ' +' + w.damage_bonus : ''} ${w.damage_type}</span>` : ''}${w.attack_bonus ? html`<span style="font-size:.7rem;"> +${w.attack_bonus} hit</span>` : ''}</span>`)}
        ${eqA.map(a => html`<span style="font-size:.75rem;padding:2px 8px;border-radius:10px;background:color-mix(in srgb, var(--sp-primary) 40%, transparent);border:1px solid var(--sp-border);color:var(--sp-text);" title="${armorTitle(a)}" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="feat-tooltip">${a.armor_category === 'Shield' ? raw('&#9694;') : raw('&#9651;')} ${a.armor_name} <span style="color:var(--sp-muted);font-size:.7rem;">${IS_DCC ? dccArmorLabel(a) : a.armor_category === 'Shield' ? '+' + (a.armor_class_base + a.ac_bonus) + ' AC' : (a.armor_class_base + a.ac_bonus) + ' AC'}</span></span>`)}</div>` : ''}
      ${c.conditions.length ? html`<div class="d-flex flex-wrap gap-1 mt-2">${c.conditions.map(x => html`<span class="badge cond-tip" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="feat-tooltip" title="${d.conditions[x] || ''}" style="background:var(--ttrpg-primary);color:var(--ttrpg-accent);border:1px solid var(--ttrpg-accent);font-size:.8rem;padding:3px 8px;cursor:help;">&#9763; ${x}</span>`)}</div>` : ''}
      ${c.skills.length ? html`<div class="d-flex flex-wrap gap-2 mt-2" style="font-size:.75rem;color:var(--sp-muted);">${c.skills.map(s => html`<span>${s.proficient ? raw('<span style="color:var(--ttrpg-accent);">&#9733;</span>') : ''}${s.skill_name} <strong style="color:var(--ttrpg-text);">${sgn(s.bonus)}</strong></span>`)}</div>` : ''}
      ${c.feats.length ? html`<div class="d-flex flex-wrap gap-1 mt-2">${c.feats.map(f => html`<span class="feat-chip" data-bs-toggle="tooltip" data-bs-placement="bottom" data-bs-custom-class="feat-tooltip" title="${f.description || 'No description.'}">&#10022; ${f.feat_name}</span>`)}</div>` : ''}
      ${prepared.length ? html`<div class="d-flex flex-wrap gap-1 mt-2">${prepared.map(cs => { const lib = cs.lib || {}; return html`<span class="spell-chip" data-sname="${cs.spell_name}" data-slevel="${ordLvl(cs.spell_level)}" data-sschool="${cs.school}" data-scast="${lib.casting_time || ''}" data-srange="${lib.range_text || ''}" data-sdur="${lib.duration || ''}" data-sconc="${cs.lib ? lib.concentration : 0}" data-sritual="${cs.lib ? lib.ritual : 0}" data-scomp="${lib.components || ''}" data-sdesc="${lib.description ? lib.description.slice(0, 280) : cs.notes}" data-sdesc-long="${lib.description && lib.description.length > 280 ? '1' : '0'}" style="display:inline-block;font-size:.75rem;padding:2px 8px;border-radius:10px;background:color-mix(in srgb, #7755cc 12%, transparent);border:1px solid color-mix(in srgb, #7755cc 50%, transparent);color:#4b2b96;cursor:help;white-space:nowrap;">&#10024; ${cs.spell_name} <span style="font-size:.68rem;opacity:.75;">${ordLvl(cs.spell_level)}</span></span>`; })}</div>` : ''}
    </div></div></div>

  <div class="col-12" id="dice-panel" style="display:none;"><div class="ttrpg-card p-3"><div class="d-flex gap-3 flex-wrap">
    <div style="flex:1 1 320px;">
      <div class="d-flex align-items-center gap-2 mb-2 flex-wrap"><label class="small text-muted mb-0">Count</label>
        <div class="d-flex align-items-center" style="gap:2px;"><button class="btn btn-sm btn-outline-secondary px-2 py-0" onclick="stepDiceCount(-1)" style="line-height:1.6;">&#8722;</button><input type="number" id="dice-count" value="1" min="1" max="20" class="form-control form-control-sm text-center" style="width:52px;"><button class="btn btn-sm btn-outline-secondary px-2 py-0" onclick="stepDiceCount(1)" style="line-height:1.6;">&#43;</button></div>
        <label class="small text-muted mb-0 ms-1">Die</label>${[4, 6, 8, 10, 12, 20, 100, 2].map(s => html`<button class="btn btn-sm btn-outline-secondary dice-btn" data-sides="${s}" onclick="selectDie(${s})" style="min-width:38px;">d${s}</button>`)}</div>
      <div class="d-flex align-items-center gap-2 mb-2" id="adv-row"><label class="small text-muted mb-0">Mode</label><div class="btn-group btn-group-sm" role="group"><button id="adv-normal" class="btn btn-sm btn-outline-secondary" onclick="setAdvMode('normal')">Normal</button><button id="adv-adv" class="btn btn-sm btn-outline-secondary" onclick="setAdvMode('advantage')">Adv</button><button id="adv-dis" class="btn btn-sm btn-outline-secondary" onclick="setAdvMode('disadvantage')">Disadv</button></div></div>
      <div class="d-flex align-items-center gap-2 mb-2 flex-wrap"><label class="small text-muted mb-0">Mod</label>
        <button type="button" class="btn btn-sm btn-outline-secondary" style="min-width:28px;padding:0 6px;" onclick="var i=document.getElementById('dice-modifier');i.value=(parseInt(i.value)||0)-1">&#8722;</button>
        <input type="number" id="dice-modifier" value="0" class="form-control form-control-sm text-center" style="width:58px;">
        <button type="button" class="btn btn-sm btn-outline-secondary" style="min-width:28px;padding:0 6px;" onclick="var i=document.getElementById('dice-modifier');i.value=(parseInt(i.value)||0)+1">+</button>
        ${modRows.map(([label, val]) => html`<button class="btn btn-sm btn-outline-secondary stat-mod-btn" data-stat="${label}" onclick="setMod(parseInt(this.dataset.mod))" data-mod="${val}" title="${label}: ${sgn(val)}">${label}<br><span style="font-size:.65rem;">${sgn(val)}</span></button>`)}
        ${IS_DCC ? html`<button class="btn btn-sm btn-outline-secondary stat-mod-btn" data-stat="EVADE" onclick="diceQuickSet(${c.evade_bonus}, 'Evade'); sysSetRollType('evade');" title="Evade: d20 + 2 + Dex Mod + buffs">EVADE<br><span style="font-size:.65rem;">${sgn(c.evade_bonus)}</span></button>` : ''}</div>
      <div id="dice-system-panel" style="display:none;"></div>
      <div class="d-flex gap-2 align-items-center flex-wrap"><input type="text" id="dice-label" autocomplete="off" class="form-control form-control-sm" placeholder="Label (optional)…" style="max-width:180px;"><button class="btn btn-ttrpg" onclick="doRoll()"><span class="dice-ico">&#127922;</span> Roll</button><button class="btn btn-sm btn-outline-secondary" onclick="resetDice()" title="Reset to 1d20 +0">&#8635;</button><button class="btn btn-sm btn-outline-secondary" onclick="clearDiceFeed()" title="Clear feed">&#128465;</button></div>
      <div id="dice-quicklabels" class="d-flex gap-1 mt-1 flex-wrap"></div>
      <div id="dice-result" class="mt-3" style="display:none;"><div id="dice-result-inner" style="background:var(--ttrpg-surface);border:1px solid var(--ttrpg-accent);border-radius:8px;padding:10px 14px;font-size:.95rem;"></div></div></div>
    <div style="flex:1 1 260px;min-width:220px;max-height:320px;overflow-y:auto;" id="dice-feed-box"><div class="small text-muted text-uppercase mb-1" style="letter-spacing:.06em;"><span class="dice-ico">&#127922;</span> Roll Feed</div><div id="dice-feed-list"><p class="small text-muted">No rolls yet.</p></div></div></div>
    ${c.skills.length || c.weapons.length || c.spells.length || c.armor.length || c.feats.length || IS_DCC ? html`<div class="dice-quickref" id="dice-quickref">
      <div class="qref-title">Quick Reference <span class="qref-hint">&#8212; click a skill or weapon to load the roll &middot; click a heading to fold it</span></div>
      ${IS_DCC ? html`<div class="qref-row" data-qref="hotlist"><span class="qref-label">Hotlist</span><div class="qref-chips">${!hot.length ? raw('<span class="qref-chip" style="opacity:.7;">&#9889; Empty &mdash; tick <b>Hotlist</b> on an item in Inventory (10 slots)</span>') : ''}
        ${hot.map(item => html`<button class="qref-chip qref-click${can ? ' qref-has-use' : ''}" onclick='hotlistQuickRoll(${J(item.item_name)}, ${J(item.notes || '')})' title="${item.notes ? item.item_name + ' — ' + item.notes : 'Load ' + item.item_name + ' into the roller'}${item.quantity > 1 ? ` (x${item.quantity})` : ''}">&#9889; ${item.item_name}${item.quantity > 1 ? html` <span class="qref-sub">x${item.quantity}</span>` : ''}</button>${can ? html`<button type="button" class="qref-use" onclick='hotlistUse(${item.item_id}, ${item.quantity}, ${J(item.item_name)})' title="Use one ${item.item_name} (${item.quantity} left)${item.quantity <= 1 ? ' — removes it from your inventory' : ''}">&#8722;1</button>` : ''}`)}</div></div>` : ''}
      ${c.skills.length ? html`<div class="qref-row" data-qref="skills"><span class="qref-label">Skills</span><div class="qref-chips">${c.skills.map(s => html`<button class="qref-chip qref-click" onclick='diceQuickSet(${s.bonus || 0}, ${J(s.skill_name)})' title="Roll ${s.skill_name} check (d20 ${sgn(s.bonus || 0)})">${s.proficient ? raw('&#9733; ') : ''}${s.skill_name} <span class="qref-sub">${sgn(s.bonus || 0)}</span></button>`)}</div></div>` : ''}
      ${c.weapons.length ? html`<div class="qref-row" data-qref="weapons"><span class="qref-label">Weapons</span><div class="qref-chips">${c.weapons.map(w => html`<button class="qref-chip qref-click" onclick='weaponQuickRoll(${J(w.damage_dice || '')}, ${w.damage_bonus || 0}, ${w.attack_bonus || 0}, ${J(w.weapon_name)})' title="Roll ${w.weapon_name}${w.damage_dice ? ` damage — ${w.damage_dice}${w.damage_bonus ? '+' + w.damage_bonus : ''} ${w.damage_type}` : ` attack (d20 ${sgn(w.attack_bonus || 0)})`}">&#9876; ${w.weapon_name} <span class="qref-sub">${w.damage_dice ? `${w.damage_dice}${w.damage_bonus ? '+' + w.damage_bonus : ''} ${w.damage_type}` : sgn(w.attack_bonus || 0)}</span></button>`)}</div></div>` : ''}
      ${c.spells.length ? html`<div class="qref-row" data-qref="spells"><span class="qref-label">Spells</span><div class="qref-chips">${c.spells.map(cs => { const dmg = cs.lib ? cs.lib.damage_dice : ''; return dmg
        ? html`<button class="qref-chip qref-click" onclick='diceQuickSetDamage(${J(dmg)}, ${J(cs.spell_name + ' damage')})' title="Roll ${cs.spell_name} damage (${dmg}${cs.lib.damage_type ? ' ' + cs.lib.damage_type : ''})">&#10039; ${cs.spell_name} <span class="qref-sub">${dmg}</span></button>`
        : html`<span class="qref-chip" title="${cs.spell_level === 0 ? 'Cantrip' : 'Level ' + cs.spell_level}${cs.school ? ' · ' + cs.school : ''}">&#10039; ${cs.spell_name} <span class="qref-sub">${cs.spell_level === 0 ? 'C' : 'L' + cs.spell_level}${cs.prepared ? raw(' &#10003;') : ''}</span></span>`; })}</div></div>` : ''}
      ${c.armor.length ? html`<div class="qref-row" data-qref="armor"><span class="qref-label">Armor</span><div class="qref-chips">${c.armor.map(a => html`<span class="qref-chip" title="${a.armor_category}">${a.armor_category === 'Shield' ? raw('&#9694;') : raw('&#9651;')} ${a.armor_name} <span class="qref-sub">${IS_DCC ? dccArmorLabel(a) : (a.armor_class_base + a.ac_bonus) + ' AC'}${a.equipped ? raw(' &#10003;') : ''}</span></span>`)}</div></div>` : ''}
      ${c.feats.length ? html`<div class="qref-row" data-qref="feats"><span class="qref-label">Feats</span><div class="qref-chips">${c.feats.map(f => html`<span class="qref-chip" title="${f.description || ''}">&#10022; ${f.feat_name}</span>`)}</div></div>` : ''}
    </div>` : ''}</div></div>

  <div class="col-12"><div class="ttrpg-card p-3">
    ${IS_DCC ? html`<h6 class="text-muted text-uppercase mb-1" style="letter-spacing:.08em;">The Five Core Stats</h6>
      <div class="small text-muted mb-3">Top number is <b>Unenhanced</b> (your body). Bottom is <b>Enhanced</b> (with gear &amp; buffs) &mdash; the modifier comes from that one. Blank Enhanced = same as Unenhanced.</div>
      <div class="d-flex gap-2 flex-wrap">${keys.map(k => { const field = k + '_val'; return html`<div class="attr-box" style="min-width:96px;"><div class="label" title="${d.dcc_stat_names[k]}">${k.toUpperCase()}</div>
        ${can ? html`<div class="attr-step"><button type="button" class="attr-stepbtn" onclick="stepAttr('${field}','score',-1,this)" title="&#8722;1">&minus;</button><div class="score editable" data-field="${field}" onclick="startAttrEdit(this, false)" title="Unenhanced">${c.scores[k]}</div><button type="button" class="attr-stepbtn" onclick="stepAttr('${field}','score',1,this)" title="+1">+</button></div>
          <div class="d-flex align-items-center justify-content-center gap-1 my-1"><span class="small text-muted" title="Enhanced score (gear, buffs)">Enh.</span><input type="number" class="form-control form-control-sm text-center dcc-enh" data-stat="${k}" style="width:58px;padding:0 2px;" min="1" max="999" value="${dcc.enh[k] ?? ''}" placeholder="${c.scores[k]}" onchange="saveField('dcc_enh_${k}', this.value, () => reloadKeepTab())"></div>
          <div class="mod" data-field="${field}" title="From Table 2 (Stat Mods) on the Enhanced score">${sgn(c.stat_mods[k])}</div>`
        : html`<div class="score" data-field="${field}">${c.scores[k]}</div><div class="small text-muted">Enh. ${c.enhanced[k]}</div><div class="mod" data-field="${field}">${sgn(c.stat_mods[k])}</div>`}</div>`; })}
        ${can ? html`<div class="attr-box" style="min-width:110px;border-style:dashed;"><div class="label" title="3 per Level gained; spend them on any Stat">Stat points</div><input type="number" class="form-control form-control-sm text-center" style="width:64px;margin:6px auto;" min="0" value="${dcc.stat_points}" onchange="saveField('dcc_stat_points', this.value, () => reloadKeepTab())"><div class="small text-muted">to spend</div></div>` : ''}</div>`
    : html`<h6 class="text-muted text-uppercase mb-3" style="letter-spacing:.08em;">Attributes</h6>
      <div class="d-flex gap-2 flex-wrap">${['str', 'dex', 'con', 'int', 'wis', 'cha'].map(k => { const field = k + '_val', score = c[field], m = c.modifiers[k]; return html`<div class="attr-box"><div class="label">${k.toUpperCase()}</div>
        ${can ? html`<div class="attr-step"><button type="button" class="attr-stepbtn" onclick="stepAttr('${field}','score',-1,this)" title="&#8722;1">&minus;</button><div class="score editable" data-field="${field}" onclick="startAttrEdit(this, false)">${score}</div><button type="button" class="attr-stepbtn" onclick="stepAttr('${field}','score',1,this)" title="+1">+</button></div>
          <div class="attr-step"><button type="button" class="attr-stepbtn" onclick="stepAttr('${field}','mod',-1,this)" title="&#8722;1 modifier">&minus;</button><div class="mod editable" data-field="${field}" onclick="startAttrEdit(this, true)">${sgn(m)}</div><button type="button" class="attr-stepbtn" onclick="stepAttr('${field}','mod',1,this)" title="+1 modifier">+</button></div>`
        : html`<div class="score" data-field="${field}">${score}</div><div class="mod" data-field="${field}">${sgn(m)}</div>`}</div>`; })}</div>`}</div></div>

  <div class="col-12"><div class="ttrpg-card p-3">
    <ul class="nav nav-tabs mb-3" id="sheetTabs">
      ${[['resources', 'Resources', c.resources.length], ['skills', 'Skills', c.skills.length], ['inventory', 'Inventory', c.inventory.length], ['weapons', 'Weapons', c.weapons.length], ['armor', 'Armor', c.armor.length], ['currency', IS_DCC ? 'Gold' : 'Currency', 0], ...(IS_DCC ? [['crawler', 'Crawler', 0]] : []), ['notes', 'Notes', c.notes.length], ['feats', IS_DCC ? 'Achievements' : 'Feats', c.feats.length], ['spells', 'Spells', c.spells.length], ['conditions', IS_DCC ? 'Debuffs' : 'Conditions', c.conditions.length], ['reference', 'Reference', 0]]
        .map(([id, label, n], i) => html`<li class="nav-item"><button class="nav-link${i === 0 ? ' active' : ''}" data-bs-toggle="tab" data-bs-target="#tab-${id}" style="color:var(--ttrpg-accent);">${label}${pill(n)}</button></li>`)}</ul>
    <div class="tab-content">
      <div class="tab-pane fade show active" id="tab-resources">
        ${can ? html`<div class="d-flex gap-2 mb-3 flex-wrap align-items-end">
          <div><label class="form-label small text-muted mb-1">Resource name</label><input type="text" id="new_res_name" class="form-control form-control-sm" placeholder="e.g. Spell Slots" style="max-width:180px;"></div>
          <div><label class="form-label small text-muted mb-1">Qty.</label><input type="number" id="new_res_cur" class="form-control form-control-sm text-center" style="max-width:90px;" value="0"></div>
          <div><label class="form-label small text-muted mb-1">Total</label><input type="number" id="new_res_max" class="form-control form-control-sm text-center" style="max-width:90px;" value="0"></div>
          <button class="btn btn-ttrpg btn-sm" onclick="addResource()">Add</button>
          ${c.char_class ? html`<button class="btn btn-outline-secondary btn-sm" onclick="suggestResources()" title="Add spell slots and class counters (rages, ki, sorcery points…) for a ${c.char_class} ${c.level} from the synced class tables. Existing resources are never changed.">&#10024; Suggest from class</button><span id="suggest-res-msg" class="small text-muted"></span>` : ''}</div>` : ''}
        ${IS_DCC ? html`<div class="small text-muted mb-2">&#9889; <b>Mana</b> is your Intelligence score (Max Mana ${c.mana_max}) and updates when that Stat changes. Spend and regain it here.</div>` : ''}
        <div id="resource-list">${c.resources.length ? c.resources.map(r => html`<div id="res-${r.resource_id}">
          <div id="res-view-${r.resource_id}" class="d-flex align-items-center gap-2 mb-1 flex-wrap"><span style="min-width:130px; color:var(--ttrpg-accent);">${r.resource_name}</span>
            ${can ? html`<button class="btn btn-sm btn-outline-danger px-2" onclick="deltaResource(${r.resource_id}, -1)">&#8722;</button>` : ''}<span id="res-cur-${r.resource_id}" class="fw-bold" style="min-width:20px; text-align:center;">${r.current_val}</span>${can ? html`<button class="btn btn-sm btn-outline-success px-2" onclick="deltaResource(${r.resource_id}, +1)">&#43;</button>` : ''}<span class="text-muted">/ ${r.max_val}</span>
            <div id="res-pips-${r.resource_id}" class="d-flex gap-1 flex-wrap">${Array.from({ length: r.max_val }, (_, i) => html`<div class="res-pip" style="width:14px;height:14px;border-radius:50%;border:1px solid var(--ttrpg-accent);background:${i < r.current_val ? 'var(--ttrpg-accent)' : 'transparent'};"></div>`)}</div>
            ${can ? html`<button class="btn btn-sm btn-outline-secondary px-2 ms-auto" title="Edit" onclick="editToggle('res', ${r.resource_id})">&#9998;</button><button class="btn btn-sm btn-outline-danger" onclick="deleteResource(${r.resource_id})">&#10005;</button>` : ''}</div>
          ${can ? editBox('res', r.resource_id, html`<input type="text" value="${r.resource_name}" id="res-name-${r.resource_id}" class="form-control form-control-sm" style="max-width:150px;" placeholder="Name"><input type="number" value="${r.current_val}" id="res-cur-edit-${r.resource_id}" class="form-control form-control-sm" style="max-width:75px;" placeholder="Current"><input type="number" value="${r.max_val}" id="res-max-edit-${r.resource_id}" class="form-control form-control-sm" style="max-width:75px;" placeholder="Max">`) : ''}</div>`)
          : html`<p class="text-muted small">No resources yet.${can ? ' Add spell slots, ki points, rages, etc.' : ''}</p>`}</div></div>

      <div class="tab-pane fade" id="tab-skills">
        ${can ? html`<div class="mb-3"><div class="d-flex gap-2 mb-2 flex-wrap align-items-end">
          <div style="position:relative;max-width:220px;flex:1 1 160px;"><input type="text" id="new_skill_name" class="form-control form-control-sm" placeholder="Search or type skill…" autocomplete="off" oninput="skillLibSearch(this.value)" onfocus="skillLibSearch(this.value)">${suggest('skill-lib-suggestions')}</div>
          ${IS_DCC ? html`<select id="new_skill_category" class="form-select form-select-sm" style="max-width:120px;" title="Skill category">${d.dcc_skill_categories.map(x => html`<option value="${x}">${x}</option>`)}</select>
            <select id="new_skill_stat" class="form-select form-select-sm" style="max-width:150px;" title="Stat Mod this skill adds">${keys.map(k => html`<option value="${k}">${d.dcc_stat_names[k]} (${sgn(c.stat_mods[k])})</option>`)}</select>
            <div class="d-flex align-items-center gap-1"><span class="small text-muted">Rank</span><input type="number" id="new_skill_bonus" class="form-control form-control-sm text-center" style="max-width:64px;" value="1" min="0" max="20"></div><input type="hidden" id="new_skill_prof">`
          : html`<input type="number" id="new_skill_bonus" class="form-control form-control-sm" placeholder="Bonus" style="max-width:80px;" value="0"><div class="form-check align-self-center ms-1"><input class="form-check-input" type="checkbox" id="new_skill_prof"><label class="form-check-label small" for="new_skill_prof">Prof.</label></div>`}
          <button class="btn btn-ttrpg btn-sm" onclick="addSkill()">Add</button></div>
          ${IS_DCC ? raw('<div class="small text-muted">Checks roll d20 + Stat Mod + Rank. Untrained = roll with Disadvantage, no Rank. <b>Passive</b> skills are never rolled. Rank-Up: after grinding hours equal to the Rank, roll a d20 &mdash; equal or higher than the Rank means +1 Rank (use the roller\'s <i>Skill Rank-Up Check</i>).</div>') : ''}</div>` : ''}
        <div id="skill-list">${c.skills.length ? c.skills.map(s => html`<div id="skill-${s.skill_id}">
          <div id="skill-view-${s.skill_id}" class="d-flex align-items-center gap-2 mb-1">
            ${IS_DCC ? html`<span style="min-width:160px; color:var(--ttrpg-accent);">${s.skill_name}</span><span class="badge" style="background:var(--ttrpg-accent);color:var(--sp-on-accent);">Rank ${s.bonus}</span><span class="text-muted small">${s.category}${s.stat ? html` &bull; ${s.stat.toUpperCase()} ${sgn(c.stat_mods[s.stat] || 0)}` : ''}</span>
              ${s.category !== 'Passive' && s.stat ? html`<button class="btn btn-sm btn-outline-secondary py-0" style="font-size:.7rem;" onclick='openDiceFromSkill(${(c.stat_mods[s.stat] || 0) + (s.bonus || 0)}, ${J(s.skill_name)}, ${J(s.category === 'Attack' ? 'attack' : 'check')})' title="Load d20 ${sgn((c.stat_mods[s.stat] || 0) + (s.bonus || 0))} into the roller">&#127922; Roll</button>` : ''}`
            : html`<span style="min-width:160px; color:var(--ttrpg-accent);">${s.proficient ? raw('&#9733;') : raw('&#9734;')} ${s.skill_name}</span><span class="text-muted small">${sgn(s.bonus)}</span>`}
            ${can ? html`<button class="btn btn-sm btn-outline-secondary px-2 ms-auto" title="Edit" onclick="editToggle('skill', ${s.skill_id})">&#9998;</button><button class="btn btn-sm btn-outline-danger" onclick="deleteSkill(${s.skill_id})">&#10005;</button>` : ''}</div>
          ${can ? editBox('skill', s.skill_id, html`<input type="text" value="${s.skill_name}" id="skill-name-${s.skill_id}" class="form-control form-control-sm" style="max-width:160px;" placeholder="Skill name">
            ${IS_DCC ? html`<select id="skill-cat-${s.skill_id}" class="form-select form-select-sm" style="max-width:120px;">${d.dcc_skill_categories.map(x => html`<option value="${x}" ${s.category === x ? 'selected' : ''}>${x}</option>`)}</select><select id="skill-stat-${s.skill_id}" class="form-select form-select-sm" style="max-width:150px;">${keys.map(k => html`<option value="${k}" ${s.stat === k ? 'selected' : ''}>${d.dcc_stat_names[k]}</option>`)}</select><span class="small text-muted">Rank</span><input type="number" value="${s.bonus}" id="skill-bonus-${s.skill_id}" class="form-control form-control-sm text-center" style="max-width:64px;" min="0" max="20"><input type="hidden" id="skill-prof-${s.skill_id}">`
            : html`<input type="number" value="${s.bonus}" id="skill-bonus-${s.skill_id}" class="form-control form-control-sm" style="max-width:75px;" placeholder="Bonus"><div class="form-check mb-0"><input class="form-check-input" type="checkbox" id="skill-prof-${s.skill_id}" ${s.proficient ? 'checked' : ''}><label class="form-check-label small" for="skill-prof-${s.skill_id}">Prof.</label></div>`}`) : ''}</div>`)
          : html`<p class="text-muted small">No skills yet.${can ? ' Add Stealth, Perception, etc.' : ''}</p>`}</div></div>

      <div class="tab-pane fade" id="tab-inventory">
        ${can ? html`<div class="mb-3"><div class="d-flex gap-2 mb-2 flex-wrap align-items-center">
          <div style="position:relative;flex:1 1 200px;max-width:320px;"><input type="text" id="new_item_name" class="form-control form-control-sm" placeholder="Search equipment &amp; magic items, or type a custom name…" autocomplete="off" oninput="equipSearch(this.value)" onfocus="equipSearch(this.value)">${suggest('equip-suggestions', 'min-width:300px;max-height:260px;box-shadow:0 4px 12px rgba(0,0,0,.4);')}</div>
          <input type="number" id="new_item_qty" class="form-control form-control-sm" placeholder="Qty" style="max-width:65px;" value="1"><input type="text" id="new_item_notes" class="form-control form-control-sm" placeholder="Notes" style="max-width:160px;"><input type="hidden" id="new_item_weight" value="">
          ${IS_DCC ? html`<div class="form-check align-self-center"><input class="form-check-input" type="checkbox" id="new_item_hotlist"><label class="form-check-label small" for="new_item_hotlist" title="Your 10-slot Hotlist: instant access in combat">Hotlist</label></div>` : ''}
          <button class="btn btn-ttrpg btn-sm" onclick="addItem()">Add</button></div>
          <div id="equip-preview" style="display:none;border-color:var(--ttrpg-accent);" class="ttrpg-card p-3"><div class="d-flex justify-content-between align-items-start gap-2 mb-1 flex-wrap"><div><span id="equip-prev-name" style="color:var(--ttrpg-accent);font-weight:600;font-size:1rem;"></span><span id="equip-prev-cat" style="font-size:.72rem;padding:1px 6px;border-radius:8px;border:1px solid var(--sp-border);color:var(--sp-muted);background:color-mix(in srgb,var(--sp-accent) 8%,transparent);margin-left:6px;"></span></div><button class="btn btn-sm btn-outline-secondary px-2" onclick="clearEquipPick()" title="Clear selection">&#10005;</button></div><div id="equip-prev-meta" class="small text-muted mb-1"></div><div id="equip-prev-desc" class="small mt-1" style="color:var(--ttrpg-text);white-space:pre-wrap;line-height:1.5;max-height:120px;overflow-y:auto;"></div></div></div>` : ''}
        ${IS_DCC ? html`<div class="small mb-2" style="color:${hot.length > 10 ? '#dc3545' : 'var(--sp-muted)'};">&#9889; Hotlist ${hot.length} / 10 slots &mdash; items marked <b>[H]</b> appear in your hand instantly. Inventory is weightless.</div>` : ''}
        <div id="inventory-list">${c.inventory.length ? c.inventory.map(item => html`<div id="item-${item.item_id}">
          <div id="item-view-${item.item_id}" class="d-flex align-items-center gap-2 mb-1 flex-wrap"><span class="${item.equipped ? 'fw-bold' : ''}" style="min-width:160px; color:var(--ttrpg-accent);">${item.equipped ? '[E]' : ''}${IS_DCC && item.hotlist ? html`<span title="On the Hotlist">[H]</span>` : ''} ${item.item_name}</span><span class="text-muted small">x${item.quantity}</span>${item.notes ? html`<span class="text-muted small fst-italic">${item.notes}</span>` : ''}
            ${can ? html`<button class="btn btn-sm btn-outline-secondary px-2 ms-auto" title="Edit" onclick="editToggle('item', ${item.item_id})">&#9998;</button><button class="btn btn-sm btn-outline-danger" onclick="deleteItem(${item.item_id})">&#10005;</button>` : ''}</div>
          ${can ? editBox('item', item.item_id, html`<input type="text" value="${item.item_name}" id="item-name-${item.item_id}" class="form-control form-control-sm" style="max-width:160px;" placeholder="Item name"><input type="number" value="${item.quantity}" id="item-qty-${item.item_id}" class="form-control form-control-sm" style="max-width:65px;" placeholder="Qty"><input type="text" value="${item.notes}" id="item-notes-${item.item_id}" class="form-control form-control-sm" style="max-width:160px;" placeholder="Notes"><div class="form-check mb-0"><input class="form-check-input" type="checkbox" id="item-equip-${item.item_id}" ${item.equipped ? 'checked' : ''}><label class="form-check-label small" for="item-equip-${item.item_id}">Equipped</label></div>${IS_DCC ? html`<div class="form-check mb-0"><input class="form-check-input" type="checkbox" id="item-hot-${item.item_id}" ${item.hotlist ? 'checked' : ''}><label class="form-check-label small" for="item-hot-${item.item_id}">Hotlist</label></div>` : ''}`) : ''}</div>`)
          : html`<p class="text-muted small">No items yet.</p>`}</div></div>

      <div class="tab-pane fade" id="tab-weapons">
        ${IS_DCC ? raw('<div class="small text-muted mb-2">&#9876; <b>Attacks:</b> To Hit = your Weapon Skill\'s Stat Mod + its Rank (put that in <i>Attack bonus</i>). Damage = the weapon\'s dice + Stat Mod (<i>Damage bonus</i>) plus the Rank damage die from Table 37 &mdash; the roller shows it under <i>Damage</i>. A Critical Hit doubles the base dice.</div>') : ''}
        ${eqW.length ? html`<div class="p-2 mb-3 rounded" style="background:color-mix(in srgb, var(--sp-accent) 6%, transparent);border:1px solid var(--sp-border);"><div class="small text-muted mb-1" style="font-weight:600;letter-spacing:.05em;text-transform:uppercase;">Ready</div><div class="d-flex flex-wrap gap-2">${eqW.map(w => html`<span class="d-inline-flex align-items-center gap-1 px-2 py-1 rounded" style="background:var(--sp-surface);border:1px solid var(--ttrpg-accent);font-size:.82rem;"><span style="color:var(--ttrpg-accent);font-weight:600;">${w.weapon_name}</span>${w.damage_dice ? html`<span class="text-muted small">${w.damage_dice}${w.damage_bonus ? ' +' + w.damage_bonus : ''} ${w.damage_type}</span>` : ''}${w.attack_bonus ? html`<span style="color:var(--ttrpg-accent);font-size:.75rem;">+${w.attack_bonus} atk</span>` : ''}</span>`)}</div></div>` : ''}
        ${can ? html`<div class="mb-3"><div class="d-flex gap-2 flex-wrap align-items-end mb-1"><div style="position:relative;max-width:260px;flex:1 1 180px;"><input type="text" id="new_weap_name" class="form-control form-control-sm" placeholder="Weapon name or search library…" autocomplete="off" oninput="weapLibSearch(this.value)" onfocus="weapLibSearch(this.value)">${suggest('weap-suggestions')}</div><button class="btn btn-ttrpg btn-sm" onclick="addWeaponToChar()">Add</button><button class="btn btn-outline-secondary btn-sm" onclick="toggleCustomWeapForm()" title="Add a weapon with full stats">+ Custom</button></div>
          ${['lib_id', 'category', 'range', 'damage_dice', 'damage_type', '2h_dice', '2h_type', 'range_normal', 'range_long', 'properties', 'notes'].map(f => html`<input type="hidden" id="new_weap_${f}" value="${f.startsWith('range_') ? '0' : ''}">`)}
          <div id="custom-weap-form" style="display:none;margin-top:8px;padding:12px;background:var(--sp-surface);border:1px solid var(--sp-border);border-radius:6px;"><div class="small fw-bold mb-2" style="color:var(--ttrpg-accent);">Custom Weapon</div>
            <div class="row g-2 mb-2"><div class="col-sm-5"><label class="form-label small text-muted mb-1">Name *</label><input type="text" id="cw_name" class="form-control form-control-sm" placeholder="Vorpal Sword"></div><div class="col-sm-4"><label class="form-label small text-muted mb-1">Category</label><select id="cw_category" class="form-select form-select-sm"><option value="">— pick —</option><option>Simple Melee</option><option>Simple Ranged</option><option>Martial Melee</option><option>Martial Ranged</option><option>Other</option></select></div><div class="col-sm-3"><label class="form-label small text-muted mb-1">Range type</label><select id="cw_range" class="form-select form-select-sm"><option value="">—</option><option>Melee</option><option>Ranged</option></select></div></div>
            <div class="row g-2 mb-2"><div class="col-sm-3"><label class="form-label small text-muted mb-1">Damage Dice</label><input type="text" id="cw_dmg_dice" class="form-control form-control-sm" placeholder="1d8"></div><div class="col-sm-3"><label class="form-label small text-muted mb-1">Damage Type</label><input type="text" id="cw_dmg_type" class="form-control form-control-sm" placeholder="slashing"></div><div class="col-sm-3"><label class="form-label small text-muted mb-1">+X to Hit</label><input type="number" id="cw_atk_bonus" class="form-control form-control-sm" value="0" min="-5" max="20"></div><div class="col-sm-3"><label class="form-label small text-muted mb-1">+X Damage</label><input type="number" id="cw_dmg_bonus" class="form-control form-control-sm" value="0" min="-5" max="20"></div></div>
            <div class="row g-2 mb-2"><div class="col-sm-3"><label class="form-label small text-muted mb-1">2H Dice</label><input type="text" id="cw_2h_dice" class="form-control form-control-sm" placeholder="1d10"></div><div class="col-sm-3"><label class="form-label small text-muted mb-1">2H Type</label><input type="text" id="cw_2h_type" class="form-control form-control-sm" placeholder="slashing"></div><div class="col-sm-3"><label class="form-label small text-muted mb-1">Range (normal ft)</label><input type="number" id="cw_range_normal" class="form-control form-control-sm" value="0" min="0"></div><div class="col-sm-3"><label class="form-label small text-muted mb-1">Range (long ft)</label><input type="number" id="cw_range_long" class="form-control form-control-sm" value="0" min="0"></div></div>
            <div class="row g-2 mb-3"><div class="col-sm-6"><label class="form-label small text-muted mb-1">Properties</label><input type="text" id="cw_properties" class="form-control form-control-sm" placeholder="finesse, thrown, versatile…"></div><div class="col-sm-6"><label class="form-label small text-muted mb-1">Notes</label><input type="text" id="cw_notes" class="form-control form-control-sm" placeholder="Attunement, silvered, magic…"></div></div>
            <div class="d-flex gap-2"><button class="btn btn-ttrpg btn-sm" onclick="addCustomWeapon()">Add Weapon</button><button class="btn btn-outline-secondary btn-sm" onclick="toggleCustomWeapForm()">Cancel</button></div></div></div>` : ''}
        <div id="weapon-list">${c.weapons.length ? c.weapons.map(w => html`<div id="char-weapon-${w.char_weapon_id}" class="d-flex align-items-start gap-2 mb-2 p-2 rounded flex-wrap" style="background:var(--sp-surface);border:1px solid var(--sp-border);">
          ${can ? html`<button class="btn btn-sm px-2 flex-shrink-0" style="${w.equipped ? 'background:var(--ttrpg-accent);color:var(--sp-on-accent);border-color:var(--ttrpg-accent);' : 'border-color:var(--sp-border);color:var(--sp-muted);'}" onclick="toggleWeapEquip(${w.char_weapon_id}, ${w.equipped})" title="${w.equipped ? 'Stow' : 'Ready'}">${w.equipped ? raw('&#9741;') : raw('&#9675;')}</button>` : ''}
          <div class="flex-grow-1 min-width-0"><div class="d-flex align-items-center gap-2 flex-wrap"><span style="color:var(--ttrpg-accent);font-weight:600;">${w.weapon_name}</span>${w.weapon_category ? html`<span style="font-size:.7rem;padding:1px 6px;border-radius:8px;border:1px solid var(--sp-border);color:var(--ttrpg-accent);background:color-mix(in srgb, var(--sp-primary) 25%, transparent);">${w.weapon_category}</span>` : ''}${w.weapon_range ? html`<span style="font-size:.7rem;color:var(--sp-muted);">${w.weapon_range}</span>` : ''}${w.equipped ? raw('<span style="font-size:.7rem;color:var(--ttrpg-accent);">&#9741; Ready</span>') : raw('<span style="font-size:.7rem;color:var(--sp-muted);">Stowed</span>')}</div>
            <div class="small text-muted mt-1 d-flex flex-wrap gap-3">${w.damage_dice ? html`<span><strong style="color:var(--sp-text);">${w.damage_dice}</strong>${w.damage_bonus ? html`<strong style="color:var(--ttrpg-accent);"> +${w.damage_bonus}</strong>` : ''} ${w.damage_type}</span>` : ''}${w.two_handed_damage_dice ? html`<span>2H: ${w.two_handed_damage_dice} ${w.two_handed_damage_type}</span>` : ''}
              ${w.weapon_range === 'Ranged' && w.range_normal ? html`<span>Range ${w.range_normal}/${w.range_long} ft</span>` : w.range_normal ? html`<span>Throw ${w.range_normal}/${w.range_long} ft</span>` : ''}${w.attack_bonus ? html`<span style="color:var(--ttrpg-accent);">+${w.attack_bonus} to hit</span>` : ''}
              ${w.properties ? html`<span class="fst-italic">${w.properties.split(',').map((p, i, arr) => { const pn = p.trim(); const pd = d.weapon_props[pn.split('(')[0].trim().toLowerCase()] || ''; return html`${pd ? html`<span data-bs-toggle="tooltip" data-bs-placement="top" data-bs-custom-class="feat-tooltip" title="${pd}" style="cursor:help;border-bottom:1px dotted var(--sp-muted);">${pn}</span>` : pn}${i < arr.length - 1 ? ', ' : ''}`; })}</span>` : ''}${w.notes ? html`<span class="fst-italic">${w.notes}</span>` : ''}</div></div>
          ${can ? html`<div class="d-flex gap-1 flex-shrink-0 align-items-start"><button class="btn btn-sm btn-outline-secondary px-2" onclick="toggleWeapEdit(${w.char_weapon_id})" title="Edit">&#9998;</button><button class="btn btn-sm btn-outline-danger px-2" onclick="deleteWeapEntry(${w.char_weapon_id})" title="Remove">&#10005;</button></div>
            <div id="weap-edit-${w.char_weapon_id}" class="w-100 mt-1" style="display:none;"><div class="d-flex gap-2 flex-wrap align-items-end" style="background:var(--sp-bg);border:1px solid var(--sp-border);border-radius:6px;padding:8px;"><div><label class="form-label small text-muted mb-1">+X to hit</label><input type="number" id="weap-atk-${w.char_weapon_id}" value="${w.attack_bonus}" min="0" max="9" class="form-control form-control-sm" style="max-width:65px;"></div><div><label class="form-label small text-muted mb-1">+X damage</label><input type="number" id="weap-dmg-${w.char_weapon_id}" value="${w.damage_bonus}" min="0" max="9" class="form-control form-control-sm" style="max-width:65px;"></div><div class="flex-grow-1"><label class="form-label small text-muted mb-1">Notes</label><input type="text" id="weap-notes-${w.char_weapon_id}" value="${w.notes}" class="form-control form-control-sm" placeholder="Attunement, special rules, silvered…"></div><button class="btn btn-ttrpg btn-sm" onclick="saveWeapEntry(${w.char_weapon_id})">Save</button><button type="button" class="btn btn-outline-secondary btn-sm" onclick="toggleWeapEdit(${w.char_weapon_id})">Cancel</button></div></div>` : ''}</div>`)
          : html`<p class="text-muted small" id="weapon-empty-msg">No weapons yet.${can ? ' Search the library or type a custom name above.' : ''}</p>`}</div></div>

      <div class="tab-pane fade" id="tab-armor">
        ${IS_DCC ? html`<div class="small text-muted mb-2">&#9651; In Dungeon Crawler Carl armor gives <b>Damage Resistance (DR)</b>, not AC &mdash; the AC numbers here are ignored. Set your armor's DR on the <b>Crawler</b> tab (currently DR ${c.dr_total}).</div>` : ''}
        ${eqA.length ? html`<div class="p-2 mb-3 rounded" style="background:color-mix(in srgb, var(--sp-accent) 6%, transparent);border:1px solid var(--sp-border);"><div class="small text-muted mb-1" style="font-weight:600;letter-spacing:.05em;text-transform:uppercase;">Equipped</div><div class="d-flex flex-wrap gap-2 align-items-center">${eqA.map(a => html`<span class="d-inline-flex align-items-center gap-1 px-2 py-1 rounded" style="background:var(--sp-surface);border:1px solid var(--ttrpg-accent);font-size:.82rem;"><span style="color:var(--ttrpg-accent);font-weight:600;">${a.armor_name}</span><span class="text-muted small">${IS_DCC ? dccArmorLabel(a) : a.armor_category === 'Shield' ? '+' + (a.armor_class_base + a.ac_bonus) + ' AC' : (a.armor_class_base + a.ac_bonus) + ' AC base'}</span></span>`)}<span class="ms-auto small text-muted" id="ac-suggest-label"></span></div></div>` : ''}
        ${can ? html`<div class="mb-3"><div class="d-flex gap-2 flex-wrap align-items-end mb-2"><div style="position:relative;max-width:240px;flex:1 1 180px;"><input type="text" id="new_armor_name" class="form-control form-control-sm" placeholder="Armor name — or search library…" autocomplete="off" oninput="armorLibSearch(this.value)" onfocus="armorLibSearch(this.value)">${suggest('armor-suggestions')}</div><button class="btn btn-ttrpg btn-sm" onclick="addArmorToChar()">Add</button></div>
          <input type="hidden" id="new_armor_lib_id" value=""><input type="hidden" id="new_armor_category" value=""><input type="hidden" id="new_armor_class_base" value="0"><input type="hidden" id="new_armor_dex_bonus" value="0"><input type="hidden" id="new_armor_max_dex" value=""><input type="hidden" id="new_armor_notes" value=""></div>` : ''}
        <div id="armor-list">${c.armor.length ? c.armor.map(a => html`<div id="char-armor-${a.char_armor_id}" class="d-flex align-items-start gap-2 mb-2 p-2 rounded flex-wrap" style="background:var(--sp-surface);border:1px solid var(--sp-border);">
          ${can ? html`<button class="btn btn-sm px-2 flex-shrink-0" id="armor-equip-btn-${a.char_armor_id}" style="${a.equipped ? 'background:var(--ttrpg-accent);color:var(--sp-on-accent);border-color:var(--ttrpg-accent);' : 'border-color:var(--sp-border);color:var(--sp-muted);'}" onclick="toggleArmorEquip(${a.char_armor_id}, ${a.equipped})" title="${a.equipped ? 'Stow' : 'Equip'}">${a.equipped ? raw('&#9741;') : raw('&#9675;')}</button>` : ''}
          <div class="flex-grow-1 min-width-0"><div class="d-flex align-items-center gap-2 flex-wrap"><span style="color:var(--ttrpg-accent);font-weight:600;">${a.armor_name}</span>${a.armor_category ? html`<span style="font-size:.7rem;padding:1px 6px;border-radius:8px;border:1px solid var(--sp-border);color:var(--ttrpg-accent);background:color-mix(in srgb, var(--sp-primary) 25%, transparent);">${a.armor_category}</span>` : ''}${a.equipped ? raw('<span style="font-size:.7rem;color:var(--ttrpg-accent);">&#9741; Equipped</span>') : raw('<span style="font-size:.7rem;color:var(--sp-muted);">Stowed</span>')}</div>
            <div class="small text-muted mt-1">${a.armor_category === 'Shield' ? `AC +${a.armor_class_base}` : `AC ${a.armor_class_base}${a.dex_bonus ? ' + DEX' + (a.max_dex_bonus !== null ? ` (max ${a.max_dex_bonus})` : '') : ''}`}${a.ac_bonus ? html`<span style="color:var(--ttrpg-accent);"> +${a.ac_bonus} magical</span>` : ''}${a.notes ? html`<span class="fst-italic ms-2">${a.notes}</span>` : ''}</div></div>
          ${can ? html`<div class="d-flex gap-1 flex-shrink-0 align-items-start"><button class="btn btn-sm btn-outline-secondary px-2" onclick="toggleArmorEdit(${a.char_armor_id})" title="Edit">&#9998;</button><button class="btn btn-sm btn-outline-danger px-2" onclick="deleteArmorEntry(${a.char_armor_id})" title="Remove">&#10005;</button></div>
            <div id="armor-edit-${a.char_armor_id}" class="w-100 mt-1" style="display:none;"><div class="d-flex gap-2 flex-wrap align-items-end" style="background:var(--sp-bg);border:1px solid var(--sp-border);border-radius:6px;padding:8px;"><div><label class="form-label small text-muted mb-1">Magic bonus (+X)</label><input type="number" id="armor-bonus-${a.char_armor_id}" value="${a.ac_bonus}" min="0" max="9" class="form-control form-control-sm" style="max-width:70px;"></div><div class="flex-grow-1"><label class="form-label small text-muted mb-1">Notes</label><input type="text" id="armor-notes-${a.char_armor_id}" value="${a.notes}" class="form-control form-control-sm" placeholder="Attunement, special rules…"></div><button class="btn btn-ttrpg btn-sm" onclick="saveArmorEntry(${a.char_armor_id})">Save</button><button type="button" class="btn btn-outline-secondary btn-sm" onclick="toggleArmorEdit(${a.char_armor_id})">Cancel</button></div></div>` : ''}</div>`)
          : html`<p class="text-muted small" id="armor-empty-msg">No armor or shields.${can ? ' Search the library or type a custom name above.' : ''}</p>`}</div></div>

      <div class="tab-pane fade" id="tab-currency"><div class="d-flex gap-4 flex-wrap align-items-end mt-2">${(IS_DCC ? [['Gold', 'gold']] : [['Gold', 'gold'], ['Silver', 'silver'], ['Copper', 'copper']]).map(([label, f]) => html`<div class="text-center"><label class="form-label" style="color:var(--ttrpg-accent);">${label}</label><br><input type="number" class="form-control text-center" style="max-width:90px; font-size:1.2rem;" value="${c[f]}" min="0" onchange="saveField('${f}', this.value)" ${can ? '' : 'readonly'}></div>`)}</div></div>

      <div class="tab-pane fade" id="tab-notes">
        ${can ? html`<div class="d-flex gap-2 mb-3"><textarea id="new_note_text" class="form-control" rows="2" placeholder="Add a note…" style="resize:vertical;"></textarea><button class="btn btn-ttrpg btn-sm align-self-start" onclick="addNote()">Add</button></div>` : ''}
        <div id="note-list">${notes.length ? notes.map(n => html`<div class="ttrpg-card p-2 mb-2" id="note-${n.note_id}" style="border-color:var(--sp-border);"><div id="note-view-${n.note_id}" class="d-flex gap-2 align-items-start"><div class="flex-grow-1"><div>${n.note_text}</div><div class="text-muted small">${n.created_at}</div></div>${can ? html`<button class="btn btn-sm btn-outline-secondary px-2 flex-shrink-0" title="Edit" onclick="editToggle('note', ${n.note_id})">&#9998;</button><button class="btn btn-sm btn-outline-danger flex-shrink-0" onclick="deleteNote(${n.note_id})">&#10005;</button>` : ''}</div>
          ${can ? html`<div id="note-edit-${n.note_id}" class="mt-2" style="display:none;"><textarea id="note-text-edit-${n.note_id}" class="form-control form-control-sm mb-2" rows="3" style="resize:vertical;">${n.note_text}</textarea><div class="d-flex gap-2"><button class="btn btn-ttrpg btn-sm" onclick="saveNote(${n.note_id})">Save</button><button type="button" class="btn btn-outline-secondary btn-sm" onclick="editToggle('note', ${n.note_id})">Cancel</button></div></div>` : ''}</div>`)
          : html`<p class="text-muted small">No notes yet.</p>`}</div></div>

      <div class="tab-pane fade" id="tab-feats">
        ${can ? html`<div class="mb-3" style="position:relative;"><div class="d-flex gap-2 mb-2 flex-wrap align-items-center"><div style="position:relative;max-width:260px;flex:1 1 200px;"><input type="text" id="new_feat_name" class="form-control form-control-sm" placeholder="Feat name — or search library…" autocomplete="off" oninput="featLibSearch(this.value)" onfocus="featLibSearch(this.value)">${suggest('feat-suggestions')}</div><button class="btn btn-ttrpg btn-sm" onclick="addFeat()">Add</button></div><textarea id="new_feat_desc" class="form-control form-control-sm" placeholder="What does this feat do?" rows="2" style="resize:vertical;"></textarea></div>` : ''}
        <div id="feat-list">${c.feats.length ? c.feats.map(f => html`<div class="ttrpg-card p-2 mb-2" id="feat-${f.feat_id}" style="border-color:var(--sp-border);"><div id="feat-view-${f.feat_id}"><div class="d-flex justify-content-between align-items-start gap-2"><span style="color:var(--ttrpg-accent);font-weight:600;">${f.feat_name}</span>${can ? html`<div class="d-flex gap-1 flex-shrink-0"><button class="btn btn-sm btn-outline-secondary px-2" title="Edit" onclick="editToggle('feat', ${f.feat_id})">&#9998;</button><button class="btn btn-sm btn-outline-danger" onclick="deleteFeat(${f.feat_id})">&#10005;</button></div>` : ''}</div>${f.description ? html`<div class="small text-muted mt-1" style="white-space:pre-wrap;">${f.description}</div>` : ''}</div>
          ${can ? html`<div id="feat-edit-${f.feat_id}" class="mt-1" style="display:none;"><input type="text" value="${f.feat_name}" id="feat-name-${f.feat_id}" class="form-control form-control-sm mb-2" placeholder="Feat name"><textarea id="feat-desc-${f.feat_id}" class="form-control form-control-sm mb-2" rows="3" style="resize:vertical;" placeholder="Description">${f.description}</textarea><div class="d-flex gap-2"><button class="btn btn-ttrpg btn-sm" onclick="saveFeat(${f.feat_id})">Save</button><button type="button" class="btn btn-outline-secondary btn-sm" onclick="editToggle('feat', ${f.feat_id})">Cancel</button></div></div>` : ''}</div>`)
          : html`<p class="text-muted small">No feats yet.${can ? ' Add Alert, Lucky, War Caster, etc.' : ''}</p>`}</div></div>

      <div class="tab-pane fade" id="tab-spells">
        ${can ? html`<div class="mb-3"><div class="d-flex gap-2 flex-wrap align-items-end mb-2"><div style="position:relative;max-width:280px;flex:1 1 200px;"><input type="text" id="new_spell_name" class="form-control form-control-sm" placeholder="Spell name — or search library…" autocomplete="off" oninput="spellLibSearch(this.value)" onfocus="spellLibSearch(this.value)">${suggest('spell-suggestions', 'max-height:240px;')}</div><button class="btn btn-ttrpg btn-sm" onclick="addSpellToChar()">Add</button><button class="btn btn-outline-secondary btn-sm" onclick="toggleCustomSpellForm()" title="Add with full details">+ Custom</button></div>
          <input type="hidden" id="new_spell_lib_id" value=""><input type="hidden" id="new_spell_level" value="0"><input type="hidden" id="new_spell_school" value="">
          <div id="custom-spell-form" style="display:none;margin-top:8px;padding:12px;background:var(--sp-surface);border:1px solid var(--sp-border);border-radius:6px;"><div class="small fw-bold mb-2" style="color:var(--ttrpg-accent);">Custom Spell</div>
            <div class="row g-2 mb-2"><div class="col-sm-5"><label class="form-label small text-muted mb-1">Name *</label><input type="text" id="cs_name" class="form-control form-control-sm" placeholder="Fireball"></div><div class="col-sm-3"><label class="form-label small text-muted mb-1">Level</label><select id="cs_level" class="form-select form-select-sm"><option value="0">Cantrip</option>${[1, 2, 3, 4, 5, 6, 7, 8, 9].map(i => html`<option value="${i}">Level ${i}</option>`)}</select></div><div class="col-sm-4"><label class="form-label small text-muted mb-1">School</label><select id="cs_school" class="form-select form-select-sm"><option value="">—</option>${['Abjuration', 'Conjuration', 'Divination', 'Enchantment', 'Evocation', 'Illusion', 'Necromancy', 'Transmutation'].map(s => html`<option>${s}</option>`)}</select></div></div>
            <div class="row g-2 mb-2"><div class="col-auto"><div class="form-check mb-0 mt-1"><input class="form-check-input" type="checkbox" id="cs_prepared"><label class="form-check-label small" for="cs_prepared">Prepared</label></div></div><div class="col"><input type="text" id="cs_notes" class="form-control form-control-sm" placeholder="Notes"></div></div>
            <div class="d-flex gap-2"><button class="btn btn-ttrpg btn-sm" onclick="addCustomSpell()">Add Spell</button><button class="btn btn-outline-secondary btn-sm" onclick="toggleCustomSpellForm()">Cancel</button></div></div></div>` : ''}
        <div id="spell-list">${c.spells.length ? [...new Set(c.spells.map(s => s.spell_level))].sort((a, b) => a - b).map(level => html`<div class="mb-3"><div class="small text-muted mb-1" style="font-weight:600;text-transform:uppercase;letter-spacing:.05em;">${levelHead(level)}</div>
          ${c.spells.filter(s => s.spell_level === level).map(cs => { const lib = cs.lib; return html`<div id="char-spell-${cs.char_spell_id}" class="ttrpg-card p-2 mb-2" style="border-color:${cs.prepared ? 'var(--ttrpg-accent)' : 'var(--sp-border)'};">
            <div class="d-flex align-items-center gap-2 flex-wrap">${can ? html`<button class="btn btn-sm px-2 flex-shrink-0" id="spell-prep-btn-${cs.char_spell_id}" style="${cs.prepared ? 'background:var(--ttrpg-accent);color:var(--sp-on-accent);border-color:var(--ttrpg-accent);' : 'border-color:var(--sp-border);color:var(--sp-muted);'}" onclick="toggleSpellPrepared(${cs.char_spell_id}, ${cs.prepared})" title="${cs.prepared ? 'Unprepare' : 'Prepare'}">${cs.prepared ? raw('&#9670;') : raw('&#9671;')}</button>` : ''}
              <span style="color:var(--ttrpg-accent);font-weight:600;flex:1 1 auto;">${cs.spell_name}</span>${cs.school ? html`<span style="font-size:.68rem;padding:1px 6px;border-radius:8px;border:1px solid var(--sp-border);color:var(--sp-muted);background:color-mix(in srgb, var(--sp-accent) 8%, transparent);">${cs.school}</span>` : ''}${lib && lib.concentration ? raw('<span style="font-size:.68rem;padding:1px 5px;border-radius:8px;border:1px solid #2244aa;color:#1a3488;">Conc</span>') : ''}${lib && lib.ritual ? raw('<span style="font-size:.68rem;padding:1px 5px;border-radius:8px;border:1px solid var(--sp-border);color:var(--sp-muted);">(R)</span>') : ''}
              ${lib && lib.description ? html`<button class="btn btn-sm btn-outline-secondary px-2 flex-shrink-0" onclick="toggleSpellDesc(${cs.char_spell_id})" title="Toggle description">&#9432;</button>` : ''}${can ? html`<button class="btn btn-sm btn-outline-secondary px-2 flex-shrink-0" onclick="toggleSpellEdit(${cs.char_spell_id})" title="Edit">&#9998;</button><button class="btn btn-sm btn-outline-danger px-2 flex-shrink-0" onclick="deleteCharSpell(${cs.char_spell_id})" title="Remove">&#10005;</button>` : ''}</div>
            ${lib && (lib.casting_time || lib.range_text || lib.duration) ? html`<div class="mt-1" style="font-size:.75rem;color:var(--sp-muted);display:flex;flex-wrap:wrap;gap:10px;">${lib.casting_time ? html`<span>&#9200; ${lib.casting_time}</span>` : ''}${lib.range_text ? html`<span>&#128247; ${lib.range_text}</span>` : ''}${lib.duration ? html`<span>&#8987; ${lib.duration}</span>` : ''}</div>` : ''}
            ${lib && lib.components ? html`<div class="mt-1" style="font-size:.72rem;color:var(--sp-muted);font-style:italic;">${lib.components}</div>` : ''}${lib && lib.classes_text ? html`<div class="mt-1" style="font-size:.7rem;color:var(--sp-muted);">Classes: ${lib.classes_text}</div>` : ''}${cs.notes ? html`<div class="mt-1 small text-muted fst-italic">&#9998; ${cs.notes}</div>` : ''}
            ${lib && lib.description ? html`<div id="spell-desc-${cs.char_spell_id}" style="display:none;"><div class="mt-2 pt-2 small" style="border-top:1px solid var(--sp-border);color:var(--ttrpg-text);white-space:pre-wrap;line-height:1.5;">${lib.description}</div></div>` : ''}
            ${can ? html`<div id="spell-edit-${cs.char_spell_id}" class="mt-2" style="display:none;"><div class="d-flex gap-2 flex-wrap align-items-end" style="background:var(--sp-bg);border:1px solid var(--sp-border);border-radius:6px;padding:8px;"><div class="flex-grow-1"><label class="form-label small text-muted mb-1">Notes</label><input type="text" id="spell-notes-${cs.char_spell_id}" value="${cs.notes}" class="form-control form-control-sm" placeholder="Cast at higher level, special use…"></div><button class="btn btn-ttrpg btn-sm" onclick="saveSpellEntry(${cs.char_spell_id})">Save</button><button type="button" class="btn btn-outline-secondary btn-sm" onclick="toggleSpellEdit(${cs.char_spell_id})">Cancel</button></div></div>` : ''}</div>`; })}</div>`)
          : html`<p class="text-muted small" id="spell-empty-msg">No spells yet.${can ? ' Search the library or type a custom spell name above.' : ''}</p>`}</div></div>

      <div class="tab-pane fade" id="tab-conditions">
        <div id="char-cond-display" class="d-flex flex-wrap gap-1 mb-2">${c.conditions.length ? c.conditions.map(x => html`<span class="badge cond-tip" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-custom-class="feat-tooltip" title="${d.conditions[x] || ''}" style="background:var(--ttrpg-primary);color:var(--ttrpg-accent);border:1px solid var(--ttrpg-accent);font-size:.85rem;padding:4px 8px;cursor:help;">${x}${can ? html`<span style="cursor:pointer;margin-left:4px;" onclick='charRemoveCondition(${J(x)})'>&#215;</span>` : ''}</span>`) : html`<p class="text-muted small mb-0" id="char-cond-empty">No active conditions.</p>`}</div>
        ${can ? html`<button class="btn btn-sm btn-outline-secondary mb-2" onclick="toggleCharCondPanel()">&#9763; Add Condition</button><div id="char-cond-panel" class="d-flex flex-wrap gap-1" style="display:none!important;">${Object.entries(condList).map(([cond, desc]) => html`<button class="btn btn-sm btn-outline-secondary py-0 cond-tip" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-custom-class="feat-tooltip" title="${desc}" onclick='charAddCondition(${J(cond)})'>${cond}</button>`)}</div>` : ''}</div>

      ${IS_DCC ? html`<div class="tab-pane fade" id="tab-crawler">
        ${(() => { const num = (key, label, hint, min = 0) => html`<div><label class="form-label small text-muted mb-1" title="${hint}">${label}</label>${can ? html`<input type="number" class="form-control form-control-sm text-center" style="max-width:90px;" min="${min}" max="999" value="${dcc[key]}" onchange="saveField('dcc_${key}', this.value, () => reloadKeepTab())">` : html`<div class="fw-bold">${dcc[key]}</div>`}</div>`;
          const txt = (key, label, hint, rows = 2) => html`<div class="col-12 col-md-4"><label class="form-label small text-muted mb-1" title="${hint}">${label}</label>${can ? html`<textarea class="form-control form-control-sm" rows="${rows}" placeholder="${hint}" onchange="saveField('dcc_${key}', this.value)">${dcc[key]}</textarea>` : html`<div style="white-space:pre-wrap;">${dcc[key] || '—'}</div>`}</div>`;
          return html`<h6 class="text-muted text-uppercase mb-2" style="letter-spacing:.08em;">Defense</h6>
          <div class="d-flex gap-3 flex-wrap align-items-end mb-3">${num('dr', 'Armor DR', 'Damage Resistance from the armor you wear — comes off every hit first')}${num('dr_buffs', 'DR buffs', 'Extra DR from spells, potions or gear right now', -99)}<div><label class="form-label small text-muted mb-1">DR total</label><div class="fw-bold" style="font-size:1.2rem;color:var(--ttrpg-accent);">${c.dr_total}</div></div>${num('evade_buffs', 'Evade buffs', 'Bonuses to Evade from gear (e.g. a Rapier) or effects', -99)}<div><label class="form-label small text-muted mb-1">Evade roll</label><div class="fw-bold" style="font-size:1.2rem;color:var(--ttrpg-accent);">d20 ${sgn(c.evade_bonus)}</div><div class="small text-muted">2 + Dex Mod ${sgn(c.stat_mods.dex)} + buffs</div></div></div>
          <h6 class="text-muted text-uppercase mb-2" style="letter-spacing:.08em;">Movement &amp; Size</h6>
          <div class="d-flex gap-3 flex-wrap align-items-end mb-3">${num('move', 'Move (ft)', 'A Move action in combat — humans move 20 ft')}${num('step', 'Step (ft)', 'A short Step — humans step 10 ft')}<div><label class="form-label small text-muted mb-1" title="Matters when attacking much bigger or smaller foes">Size</label>${can ? html`<select class="form-select form-select-sm" style="max-width:170px;" onchange="saveField('dcc_size', this.value, () => reloadKeepTab())">${d.dcc_sizes.map(([v, name]) => html`<option value="${v}" ${dcc.size === v ? 'selected' : ''}>${name}</option>`)}</select>` : html`<div class="fw-bold">${dcc.size}</div>`}</div></div>
          <h6 class="text-muted text-uppercase mb-2" style="letter-spacing:.08em;">Fame &amp; Favor</h6>
          <div class="d-flex gap-3 flex-wrap align-items-end mb-3">${num('popularity', 'Popularity', `Starts at Cha Mod × 2 (${c.stat_mods.cha * 2}). Viewers love you… or not.`)}${num('ai_favor', 'AI Favor', 'Luck the System AI grants you. Humans start with 1 (+1d2 per weapon/spell rating).')}${num('stat_points', 'Stat points to spend', '3 per Level gained — add them to any Stat')}</div>
          <h6 class="text-muted text-uppercase mb-2" style="letter-spacing:.08em;">Who you are</h6>
          <div class="row g-3 mb-3">
            <div class="col-6 col-md-3"><label class="form-label small text-muted mb-1">Crawler number</label>${can ? html`<input type="text" class="form-control form-control-sm" value="${dcc.crawler_number}" onchange="saveField('dcc_crawler_number', this.value)">` : html`<div>${dcc.crawler_number || '—'}</div>`}</div>
            <div class="col-6 col-md-3"><label class="form-label small text-muted mb-1">Gender / pronouns</label>${can ? html`<input type="text" class="form-control form-control-sm" value="${dcc.pronouns}" onchange="saveField('dcc_pronouns', this.value)">` : html`<div>${dcc.pronouns || '—'}</div>`}</div>
            <div class="col-6 col-md-3"><label class="form-label small text-muted mb-1" title="The Floor this crawler entered the dungeon">Floor entered</label>${can ? html`<input type="text" class="form-control form-control-sm" value="${dcc.floor_entered}" onchange="saveField('dcc_floor_entered', this.value)">` : html`<div>${dcc.floor_entered || '—'}</div>`}</div>
            <div class="col-6 col-md-3"><label class="form-label small text-muted mb-1" title="Race and Class are chosen on the Third Floor">Combat background</label><div class="small">${c.background || '—'} <span class="text-muted">(edit via &#9998; Edit Sheet)</span></div></div>
            ${txt('past_trauma', 'Past Trauma', 'Table 22 — what the System AI dug up')}${txt('loose_ends', 'Loose Ends', 'Table 23 — unfinished business')}${txt('regrets', 'Regrets', 'Table 24 — what you never said or did')}${txt('grind_hours', 'Grinding hours', 'Hours banked toward Rank-Up checks, per skill (e.g. "Bow 3/4")', 3)}</div>`; })()}</div>` : ''}

      <div class="tab-pane fade" id="tab-reference">
        <div class="row g-2 mb-3">
          <div class="col-sm-6"><div class="ttrpg-card p-2 h-100" style="border-color:var(--sp-border);"><div class="d-flex justify-content-between align-items-center mb-1"><span class="small fw-bold text-muted" style="text-transform:uppercase;letter-spacing:.06em;">Race</span>${isDm ? html`<a href="/ttrpg/reference/races" target="_blank" data-native class="small text-muted text-decoration-none" style="font-size:.7rem;">&#8599; library</a>` : ''}</div>
            ${myRace ? html`<div style="color:var(--ttrpg-accent);font-weight:600;">${myRace.name}</div><div class="d-flex gap-3 small text-muted mt-1 flex-wrap"><span>${myRace.size || '—'}</span><span>${myRace.speed} ft</span>${myRace.ability_bonuses ? html`<span style="color:var(--ttrpg-accent);">${myRace.ability_bonuses}</span>` : ''}${myRace.languages ? html`<span>${myRace.languages}</span>` : ''}</div>
              ${raceTraits.length ? html`<div class="d-flex flex-wrap gap-1 mt-1" id="race-traits">${raceTraits.map((t, i) => html`<span style="font-size:.68rem;padding:1px 5px;border-radius:6px;background:color-mix(in srgb, var(--sp-accent) 10%, transparent);border:1px solid var(--sp-border);color:var(--sp-muted);${i >= 5 ? 'display:none;' : ''}" ${i >= 5 ? 'class="race-trait-extra"' : ''}>${t}</span>`)}${raceTraits.length > 5 ? html`<a href="#" class="text-decoration-none more-toggle" data-target="#race-traits .race-trait-extra" data-more="${raceTraits.length - 5}" style="font-size:.68rem;color:var(--ttrpg-accent);">&#9660; +${raceTraits.length - 5} more</a>` : ''}</div>` : ''}
              ${myRace.description ? html`<div class="small text-muted mt-1" style="font-size:.72rem;">${myRace.description}</div>` : ''}`
            : c.race ? html`<div class="small text-muted fst-italic">${c.race} <span style="font-size:.72rem;">(not in library)</span></div>` : html`<div class="small text-muted fst-italic">No race set.</div>`}</div></div>
          <div class="col-sm-6"><div class="ttrpg-card p-2 h-100" style="border-color:var(--sp-border);"><div class="d-flex justify-content-between align-items-center mb-1"><span class="small fw-bold text-muted" style="text-transform:uppercase;letter-spacing:.06em;">Class</span>${isDm ? html`<a href="/ttrpg/reference/classes" target="_blank" data-native class="small text-muted text-decoration-none" style="font-size:.7rem;">&#8599; library</a>` : ''}</div>
            ${myClass ? html`<div style="color:var(--ttrpg-accent);font-weight:600;">${myClass.name}${myClass.hit_die ? html`<span style="font-size:.75rem;color:var(--sp-muted);font-weight:normal;margin-left:4px;">d${myClass.hit_die}</span>` : ''}</div>
              ${myClass.game_system === 'dcc' ? html`${myClass.proficiencies ? html`<div class="small" style="color:var(--ttrpg-accent);">${myClass.proficiencies}</div>` : ''}${myClass.description ? html`<div class="small text-muted mt-1" style="white-space:pre-wrap;font-size:.72rem;">${myClass.description}</div>` : ''}` : ''}
              <div class="d-flex gap-3 small text-muted mt-1 flex-wrap">${myClass.saving_throws ? html`<span>Saves: <span style="color:var(--ttrpg-accent);">${myClass.saving_throws}</span></span>` : ''}${myClass.spellcasting_ability ? html`<span style="font-size:.7rem;padding:1px 6px;border-radius:8px;background:color-mix(in srgb, #7c5cbf 15%, transparent);border:1px solid #7c5cbf;color:#4b2b8c;">${myClass.spellcasting_ability}</span>` : ''}</div>
              ${myClass.skill_choices ? html`<div class="small text-muted mt-1" style="white-space:pre-wrap;">${myClass.skill_choices}</div>` : ''}
              ${classSubs.length ? html`<div class="d-flex flex-wrap gap-1 mt-1 align-items-center" id="class-subs">${myClass.game_system === 'dcc' ? html`<span class="text-muted" style="font-size:.68rem;" title="DCC has no subclasses — each Class belongs to one or more Class Types">Class type:</span>` : ''}${classSubs.map((s, i) => html`<span style="font-size:.68rem;padding:1px 5px;border-radius:6px;background:color-mix(in srgb, var(--sp-accent) 10%, transparent);border:1px solid var(--sp-border);color:var(--sp-muted);${i >= 4 ? 'display:none;' : ''}" ${i >= 4 ? 'class="class-sub-extra"' : ''}>${s}</span>`)}${classSubs.length > 4 ? html`<a href="#" class="text-decoration-none more-toggle" data-target="#class-subs .class-sub-extra" data-more="${classSubs.length - 4}" style="font-size:.68rem;color:var(--ttrpg-accent);">&#9660; +${classSubs.length - 4} more</a>` : ''}</div>` : ''}`
            : c.char_class ? html`<div class="small text-muted fst-italic">${c.char_class} <span style="font-size:.72rem;">(not in library)</span></div>` : html`<div class="small text-muted fst-italic">No class set.</div>`}
            ${c.char_class ? (can && d.subclass_options.length ? html`<div class="d-flex align-items-center gap-2 mt-2"><label class="small text-muted mb-0">Subclass</label><select class="form-select form-select-sm" style="max-width:210px;" onchange="saveField('subclass', this.value, () => reloadKeepTab())"><option value="">&mdash; none &mdash;</option>${d.subclass_options.map(s => html`<option value="${s}" ${c.subclass === s ? 'selected' : ''}>${s}</option>`)}</select></div>`
              : c.subclass ? html`<div class="small mt-2"><span class="text-muted">Subclass:</span> <span style="color:var(--ttrpg-accent);font-weight:600;">${c.subclass}</span></div>`
              : can ? html`<div class="small text-muted fst-italic mt-2" style="font-size:.72rem;">Sync Subclasses on the API Settings page to pick an archetype here.</div>` : '') : ''}</div></div></div>
        ${cli || feats.length ? html`<div class="ttrpg-card p-2 mb-3" style="border-color:var(--sp-border);"><div class="small fw-bold text-muted mb-1" style="text-transform:uppercase;letter-spacing:.06em;">${c.char_class}${c.subclass ? ` (${c.subclass})` : ''} ${c.level} — Progression</div>
          ${cli ? html`<div class="d-flex gap-3 small flex-wrap mb-2"><span>Prof. bonus <span style="color:var(--ttrpg-accent);font-weight:600;">+${cli.prof_bonus}</span></span>${Object.keys(cli.slots || {}).length ? html`<span>Spell slots: ${Object.entries(cli.slots).sort((a, b) => a[0] - b[0]).map(([lvl, n]) => html`<span style="font-size:.72rem;padding:1px 6px;border-radius:8px;margin-left:2px;border:1px solid var(--ttrpg-accent);color:var(--ttrpg-accent);">L${lvl}&times;${n}</span>`)}</span>` : ''}${cli.cantrips_known ? html`<span class="text-muted">${cli.cantrips_known} cantrips</span>` : ''}${cli.spells_known ? html`<span class="text-muted">${cli.spells_known} spells known</span>` : ''}${Object.entries(cli.counters || {}).map(([label, n]) => html`<span class="text-muted">${label}: <span style="color:var(--ttrpg-accent);">${n}</span></span>`)}</div>` : ''}
          ${feats.length ? html`<div class="small fw-bold text-muted mb-1" style="text-transform:uppercase;letter-spacing:.06em;">Class Features</div>${feats.map(f => html`<details class="mb-1" style="border:1px solid var(--sp-border);border-radius:5px;padding:4px 8px;background:var(--sp-surface);"><summary style="cursor:pointer;font-size:.85rem;"><span class="text-muted" style="font-size:.72rem;">L${f.level}</span> <span style="color:var(--ttrpg-accent);font-weight:600;">${f.name}</span>${f.subclass_name ? html` <span style="font-size:.68rem;padding:1px 5px;border-radius:6px;border:1px solid var(--ttrpg-accent);color:var(--ttrpg-accent);">${f.subclass_name}</span>` : ''}${f.prerequisites ? html` <span class="text-muted fst-italic" style="font-size:.72rem;">(${f.prerequisites})</span>` : ''}</summary><div class="small mt-1" style="white-space:pre-wrap;color:var(--sp-text);">${f.description}</div></details>`)}` : html`<p class="text-muted small fst-italic mb-0">No synced features for this class — run Sync All on the API Settings page.</p>`}</div>` : ''}
        <div class="small fw-bold text-muted mb-2" style="text-transform:uppercase;letter-spacing:.06em;">Browse Libraries</div>
        <div id="ref-accordion">${[['armor', 'Armor', '🛡'], ['features', 'Class Features', '📖'], ['classes', 'Classes', '🏰'], ['conditions', 'Conditions', '☠'], ['equipment', 'Equipment', '🎒'], ['feats', 'Feats', '⭐'], ['magicitems', 'Magic Items', '🔮'], ['races', 'Races', '🧬'], ['rules', 'Rules', '📜'], ['skills', 'Skills', '🎯'], ['spells', 'Spells', '✦'], ['subclasses', 'Subclasses', '🧭'], ['traits', 'Traits', '🌿'], ['weaponprops', 'Weapon Properties', '🏷'], ['weapons', 'Weapons', '⚔']]
          .filter(([key]) => !(IS_DCC && ['subclasses', 'features', 'traits', 'feats'].includes(key)))
          .map(([key, label, icon]) => html`<div class="ref-section mb-1" style="border:1px solid var(--sp-border);border-radius:6px;overflow:hidden;"><button class="ref-section-hdr w-100 text-start d-flex justify-content-between align-items-center px-3 py-2" style="background:var(--sp-surface);border:none;color:var(--ttrpg-accent);font-size:.85rem;cursor:pointer;" onclick="refToggle('${key}')"><span>${icon} ${label}</span><span id="ref-arrow-${key}" style="font-size:.7rem;color:var(--sp-muted);">▼</span></button>
            <div id="ref-body-${key}" style="display:none;padding:8px 10px;background:var(--sp-bg);"><input type="text" id="ref-q-${key}" class="form-control form-control-sm mb-2" placeholder="Search ${label}…" oninput="refSearch('${key}', this.value)"><div id="ref-results-${key}" class="small"></div></div></div>`)}</div></div>
    </div></div></div>

  ${isDm ? html`<div class="col-12"><div class="ttrpg-card p-3"><h6 class="text-muted text-uppercase mb-3" style="letter-spacing:.08em;">DM Controls</h6><div class="d-flex flex-wrap gap-4 align-items-end">
    <form id="assign-form" class="d-flex gap-2 align-items-end"><div><label class="form-label small mb-1">Assign to Player</label><select name="user_id" class="form-select form-select-sm" style="min-width:180px;">${d.all_players.map(u => html`<option value="${u.user_id}" ${u.user_id === c.user_id ? 'selected' : ''}>${u.display_name}${u.user_id === c.user_id ? ' (current)' : ''}</option>`)}</select></div><button type="submit" class="btn btn-sm btn-ttrpg">Reassign</button></form>
    <div><label class="form-label small mb-1" title="Which rules the sheet is laid out for">Game system</label><select id="game-system-sel" class="form-select form-select-sm" style="min-width:200px;" data-current="${c.game_system}">${Object.entries(d.game_systems).map(([sid, gs]) => html`<option value="${sid}" ${c.game_system === sid ? 'selected' : ''}>${gs.name}</option>`)}</select></div>
    <form id="remove-form" class="ms-auto"><button type="submit" class="btn btn-sm btn-outline-danger">Remove Character</button></form></div></div></div>` : ''}
</div>

<div class="modal fade" id="llmPromptModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-scrollable"><div class="modal-content" style="background:var(--ttrpg-surface);border:1px solid var(--ttrpg-accent);color:var(--ttrpg-text);">
  <div class="modal-header" style="border-color:var(--ttrpg-accent);"><h5 class="modal-title" style="color:var(--ttrpg-accent);">&#127748; Image Prompt — ${c.name}</h5><button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div>
  <div class="modal-body">
    ${c.portrait_url ? html`<div id="llm-img-section" class="mb-3"><div class="d-flex align-items-center gap-2 mb-1"><span class="small text-muted text-uppercase" style="letter-spacing:.06em;">Portrait</span><span id="llm-img-size" class="small text-muted"></span><button class="btn btn-sm btn-outline-secondary ms-auto" style="font-size:.75rem;" onclick="downloadLlmImage()">&#11015; Download</button></div><img id="llm-img-preview" src="${c.portrait_url}" style="max-height:120px;border-radius:6px;border:1px solid var(--ttrpg-accent);" alt="Portrait" crossorigin="anonymous"><p class="small text-muted mt-1 mb-0">Upload this image alongside the prompt text when using a multimodal LLM (Claude, GPT-4o, etc.).</p></div><hr style="border-color:var(--sp-border);">` : ''}
    <div class="d-flex align-items-center gap-2 mb-2"><span class="small text-muted text-uppercase" style="letter-spacing:.06em;">Prompt Text</span>${can ? html`<button id="llm-ai-btn" class="btn btn-sm btn-ttrpg ms-auto" style="display:none;font-size:.75rem;" onclick="aiGeneratePortrait(this)" title="One click: Gemini generates the portrait and sets it on this character">&#10024; Generate with Gemini</button>` : ''}<button class="btn btn-sm ${can ? '' : 'ms-auto'}" style="background:var(--ttrpg-surface);color:var(--ttrpg-accent);border:1px solid var(--ttrpg-accent);font-size:.75rem;" onclick="copyLlmPrompt()">&#128203; Copy</button></div>
    <div id="llm-ai-status" class="small mb-2"></div>
    <textarea id="llm-prompt-text" class="form-control" style="font-family:monospace;font-size:.78rem;min-height:420px;background:var(--ttrpg-surface);color:var(--ttrpg-text);border-color:var(--sp-border);resize:vertical;" readonly></textarea></div>
  <div class="modal-footer" style="border-color:var(--ttrpg-accent);"><span id="llm-copy-feedback" style="font-size:.8rem;color:var(--ttrpg-accent);display:none;">Copied!</span><button type="button" class="btn btn-outline-secondary btn-sm" data-bs-dismiss="modal">Close</button></div></div></div></div>`;
}

// Page globals the verbatim sheet.js expects (the old inline <script>).
export function globals(d) {
  const c = d.char;
  const G = {
    CHAR_ID: c.character_id, CAN_EDIT: d.can_edit, CHAR_NAME: c.name, GAME_INFO: d.game, CHAR_SYSTEM: c.game_system,
    STAT_SCORES: Object.fromEntries(c.stat_keys.map(k => [k.toUpperCase(), c.enhanced[k]])),
    DCC_SLOT_VALUE: c.is_dcc ? c.hb_slot_value : 0,
    READY_WEAPONS: c.weapons.filter(w => w.equipped === 1).map(w => w.weapon_name),
    WEAPON_DICE: Object.fromEntries(c.weapons.map(w => [w.weapon_name, { dice: w.damage_dice || '', bonus: w.damage_bonus || 0 }])),
    DCC_DR: c.is_dcc ? c.dr_total : 0, DEX_MOD: c.modifiers.dex,
    ARMOR_LIST: c.armor.map(a => ({ char_armor_id: a.char_armor_id, armor_category: a.armor_category, armor_class_base: a.armor_class_base, dex_bonus: a.dex_bonus, max_dex_bonus: a.max_dex_bonus, ac_bonus: a.ac_bonus, equipped: a.equipped })),
    _refUrls: { spells: '/ttrpg/reference/spells/search', weapons: '/ttrpg/reference/weapons/search', armor: '/ttrpg/reference/armor/search', equipment: '/ttrpg/reference/equipment/search', feats: '/ttrpg/reference/feats/search', skills: '/ttrpg/reference/skills/search', races: '/ttrpg/reference/races/search', classes: '/ttrpg/reference/classes/search',
      conditions: '/ttrpg/reference/lookup/conditions', magicitems: '/ttrpg/reference/lookup/magicitems', features: '/ttrpg/reference/lookup/features', subclasses: '/ttrpg/reference/lookup/subclasses', traits: '/ttrpg/reference/lookup/traits', weaponprops: '/ttrpg/reference/lookup/weaponprops', rules: '/ttrpg/reference/lookup/rules' },
    _llmChar: {
      name: c.name, level: c.level, char_class: c.char_class, subclass: c.subclass, race: c.race, genre_label: d.genre_label, archetype: d.genre_archetype, species: d.genre_species, genre_art: d.genre_art,
      background: c.background, player: c.user_display_name, hp_current: c.hp_current, hp_max: c.hp_max, ac: c.ac, speed: c.speed, initiative_bonus: c.initiative_bonus, passive_perception: c.passive_perception,
      str_val: c.str_val, dex_val: c.dex_val, con_val: c.con_val, int_val: c.int_val, wis_val: c.wis_val, cha_val: c.cha_val, gold: c.gold, silver: c.silver, copper: c.copper, portrait_url: c.portrait_url,
      skills: c.skills.map(s => ({ name: s.skill_name, bonus: s.bonus, proficient: s.proficient })),
      feats: c.feats.map(f => ({ name: f.feat_name, description: f.description })),
      weapons: c.weapons.map(w => ({ name: w.weapon_name, damage: (w.damage_dice || '') + (w.damage_bonus ? ' +' + w.damage_bonus : '') + (w.damage_type ? ' ' + w.damage_type : ''), attack_bonus: w.attack_bonus || 0, properties: w.properties, notes: w.notes, equipped: w.equipped })),
      armor: c.armor.map(a => ({ name: a.armor_name, ac_total: a.armor_class_base + a.ac_bonus, equipped: a.equipped, notes: a.notes })),
      spells: c.spells.map(s => ({ name: s.spell_name, level: s.spell_level, school: s.school, prepared: s.prepared })),
      resources: c.resources.map(r => ({ name: r.resource_name, current: r.current_val, max: r.max_val })),
      inventory: c.inventory.map(i => ({ name: i.item_name, qty: i.quantity, notes: i.notes })),
      conditions: c.conditions.slice(),
      notes: c.notes.slice().sort((a, b) => (a.created_at < b.created_at ? 1 : -1)).map(n => n.note_text),
    },
    _pasteUploadUrl: d.can_edit ? `/ttrpg/character/${c.character_id}/portrait-paste` : null,
  };
  return G;
}
